GimCorpus.put(126,0,[[1,1,"מִי יַעֲלֶה לָּנוּ אֶל הַכְּנַעֲנִי. עַל מְקוֹמוֹת שֶׁהִפַּלְנוּ בְּגוֹרָל וַעֲדַיִן לֹא נִכְבְּשׁוּ:",1,0],[1,2,"יְהוּדָה יַעֲלֶה. שֵׁבֶט יְהוּדָה יַעֲלֶה תְּחִלָּה לִכְבֹּשׁ אֶת גּוֹרָלוֹ:",1,0],[1,3,"לְשִׁמְעוֹן אָחִיו. לְשֵׁבֶט שִׁמְעוֹן:",1,0],[1,3,"עֲלֵה אִתִּי. וְעָזְרֵנִי לִכְבּוֹשׁ אֶת מַה שֶׁנָּפַל בְּגוֹרָלִי וְיֵשׁ פּוֹתְרִין: יְהוּדָה יַעֲלֶה, הוּא עָתְנִיאֵל, הוּא יַעְבֵּץ, שֶׁאָנוּ אוֹמְרִים בְּמַסֶּכֶת תְּמוּרָה (טז א): מַה שְּׁמוֹ, יְהוּדָה אֲחִי שִׁמְעוֹן שְׁמוֹ, וּלְשִׁמְעוֹן אָחִיו אָמַר שֶׁיֵּלֵךְ אִתּוֹ:",2,0],[1,4,"בְּבֶזֶק. שֵׁם מָקוֹם:",1,0],[1,7,"שִׁבְעִים מְלָכִים וְגוֹ׳. מִכָּאן אַתָּה לָמֵד מַה גְּדוּלָּתָן וְעָשְׁרָן שֶׁל מַלְכֵי כְּנַעַן, שֶׁהֲרֵי אֲדֹנִי בֶזֶק לֹא הָיָה כְּדַאי לִמְנוֹת (יהושע יב) עִם מַלְכֵי כְּנַעַן בְּשֵׁם ׳מֶלֶךְ׳, וְכָתוּב בּוֹ כֵּן:",1,0],[1,7,"וַיְבִיאֻהוּ יְרוּשָׁלִַם. שֶׁהָלְכוּ מִשָּׁם לְהִלָּחֵם עַל יְרוּשָׁלַיִם:",2,0],[1,8,"שִׁלְּחוּ בָאֵשׁ. שִׁלְּחוּ אֵשׁ בְּכֻלָּהּ:",1,0],[1,13,"אֲחִי כָלֵב. מֵאִמּוֹ:",1,0],[1,14,"וַתְּסִיתֵהוּ. (תרגום:) וְאַמְלָכְתֵּיהּ, לְשׁוֹן נִמְלָךְ, שֶׁמְּיַעֲצִין הָאָדָם וּמַשִּׂיאִין לִבּוֹ לְדָבָר אַחֵר, נִרְאֶה לִי:",1,0],[1,14,"וַתִּצְנַח. (תרגום:) וְאִתְרְכִינַת, לִיפּוֹל לְרַגְלֵי אָבִיהָ:",2,0],[1,15,"אֶרֶץ הַנֶּגֶב. אָדָם שֶׁבֵּיתוֹ מְנֻגָּב מִכָּל טוּב, שֶׁאֵין בּוֹ אֶלָּא תּוֹרָה:",1,0],[1,15,"גֻּלֹּת מָיִם. שְׂדֵה בֵּית הַבַּעַל, (תרגום:) אֲתַר בֵּית שָׁקְיָא דְמַיָּא:",2,0],[1,16,"מֵעִיר הַתְּמָרִים. הִיא יְרִיחוֹ, שֶׁנִּתַּן לָהֶם דּוּשְׁנָהּ שֶׁל יְרִיחוֹ לְאָכְלָהּ עַד שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ, וּמִי שֶׁיִּבְנֶה בֵּית הַבְּחִירָה בְּחֶלְקוֹ יִטְּלֶנָּה, כְּדֵי שֶׁיְּהֵא לְכָל יִשְׂרָאֵל חֵלֶק בְּבֵית הַבְּחִירָה, וּנְתָנוּהָ לִבְנֵי יִתְרוֹ אַרְבַּע מֵאוֹת אַרְבָּעִים שָׁנָה, וְהַתַּלְמִידִים שֶׁבָּהֶם הִנִּיחוּהָ וְהָלְכוּ אֵצֶל עָתְנִיאֵל בֶּן קְנַז הוּא יַעְבֵּץ בְּמִדְבַּר יְהוּדָה אֲשֶׁר בְּנֶגֶב עֲרָד לִלְמוֹד תּוֹרָה:",1,0],[1,16,"וַיֵּשֶׁב אֶת הָעָם. עִם הַתַּלְמִידִים הַיּוֹשְׁבִים לְפָנָיו הוּא בִּקֵּשׁ מֵאֵת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיַּזְמִין לוֹ תַּלְמִידִים הֲגוּנִים, שֶׁנֶּאֱמַר (דברי הימים א ד:י) וַיִּקְרָא יַעְבֵּץ לֵאלֹהִים וְגוֹ׳, וְזִמֵּן לוֹ הַחֲסִידִים הַלָּלוּ:",2,0],[1,19,"כִּי לֹא לְהוֹרִישׁ. תִּרְגֵּם יוֹנָתָן: בָּתַר כֵּן דְּחָבוּ, לָא יְכִילוּ לְתָרְכָא יָת יָתְבֵי מֵישְׁרָא:",1,0],[1,21,"וְאֶת הַיְבוּסִי יֹשֵׁב יְרוּשָׁלִַם. מָחוֹז הָיָה בִּירוּשָׁלַיִם שֶׁשְּׁמוֹ יְבוּסִי (פרקי דרבי אליעזר לו), וּמִבְּנֵי אֲבִימֶלֶךְ הָיוּ, וְלֹא הוֹרִישָׁם מִפְּנֵי הַשְּׁבוּעָה (בראשית כא:כג-כד) עַד שֶׁבָּא דָוִד (שמואל ב ה:ו-ז), לְפִי שֶׁעֲדַיִן הָיָה נֶכְדּוֹ קַיָּם, וְהוּא נִשְׁבַּע לוֹ וּלְנִינוֹ וּלְנֶכְדּוֹ:",1,0],[1,22,"בֵּית אֵל. שֶׁנָּפַל בְּגוֹרָלָם (יהושע טז:א), וְאַף עַל פִּי שֶׁפֶּסֶל מִיכָה עִמָּהֶם, שֶׁהֲרֵי מִיכָה מִשֵּׁבֶט אֶפְרַיִם (שופטים יז:א), נֶאֱמַר כָּאן ׳וַה׳ עִמָּם׳, הוּא שֶׁאָמַר דָּנִיֵּאל (דניאל ט:ז): לְךָ ה׳ הַצְּדָקָה וְלָנוּ בֹּשֶׁת הַפָּנִים:",1,0],[1,23,"וַיָּתִירוּ. עַל יְדֵי אֲחֵרִים, (תרגום:) וּשְׁלָחוּ מְאַלְּלִין, וְיָתוּרוּ אֶת אֶרֶץ (במדבר יג:ב) נֶאֱמַר בַּמְרַגְּלִים עַצְמָן, וְאֵלּוּ שֶׁשָּׁלְחוּ מְרַגְּלִים נֶאֱמַר בָּהֶם וַיָּתִירוּ:",1,0],[1,24,"אֶת מְבוֹא הָעִיר. שֶׁהָיוּ נִכְנָסִים לָהּ דֶּרֶךְ הַמְּעָרָה, וְלוּז אֶחָד עוֹמֵד עַל פִּי הַמְּעָרָה וְנִכְנָסִים דֶּרֶךְ הַלּוּז לַמְּעָרָה:",1,0],[1,25,"וַיַּרְאֵם. בְּאֶצְבָּעוֹ:",1,0],[1,26,"לוּז. שֶׁגָּדְלוּ בּוֹ אֱגוֹזִים דַּקִּים, קולדר״א בְּלַעַ״ז:",1,0],[1,26,"הוּא שְׁמָהּ עַד הַיּוֹם. לֹא בִּלְבְּלָה סַנְחֵרִיב, וְלֹא הֶחֱרִיבָהּ נְבוּכַדְנֶצַּר:",2,0],[1,27,"וְלֹא הוֹרִישׁ מְנַשֶּׁה. סִפֵּר הַכָּתוּב בִּגְנוּתוֹ, שֶׁהִתְחִילוּ לִמְעוֹל בְּהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁצִּוָּה אוֹתָם (במדבר לג:נב): וְהוֹרַשְׁתֶּם אֶת כָּל יוֹשְׁבֵי הָאָרֶץ וְגוֹ׳:",1,0],[2,1,"וַיַּעַל מַלְאַךְ ה׳. שָׁנִינוּ בְּ׳סֵדֶר עוֹלָם׳ (פרק יט): זֶה הָיָה פִּנְחָס:",1,0],[2,1,"אֶל הַבֹּכִים. שֵׁם הַמָּקוֹם:",2,0],[2,1,"אַעֲלֶה אֶתְכֶם. כָּךְ הָיָה דַעְתִּי מִתְּחִלָּה לְהַעֲלוֹתְכֶם מִמִּצְרַיִם, וְכֵן עָשִׂיתִי עַל מְנָת לְהוֹרִישׁ אֶת אוֹיְבַי:",3,0],[2,3,"וְגַם אָמַרְתִּי. עַתָּה אָמַרְתִּי בְּאַפִּי:",1,0],[2,3,"לְצִדִּים. לִמְצַדְּדִים בְּצִדְּכֶם בִּגְדוּדִים וְגַיָּסוֹת לִשְׁלֹל וְלָבוֹז:",2,0],[2,6,"וַיְשַׁלַּח יְהוֹשֻׁעַ וְגוֹ׳. זֶה הַמַּעֲשֶׂה הָיָה מֻקְדָּם, אֶלָּא לְפִי שֶׁבָּא לוֹמַר (פסוק יא): וַיַּעֲשׂוּ הָרַע, הִתְחִיל לוֹמַר כֵּן: יְהוֹשֻׁעַ כְּשֶׁמֵּת, וְקִבְּלוּ לְפָנָיו לַעֲבֹד ה׳, שְׁלָחָם אִישׁ לְנַחֲלָתוֹ, וְהֵם עָבְדוּ אֶת ה׳ כָּל יָמָיו וְכָל יְמֵי הַזְּקֵנִים, וְאַחַר כָּךְ: וַיַּעֲשׂוּ בְּנֵי יִשְׂרָאֵל הָרַע:",1,0],[2,7,"אֲשֶׁר הֶאֱרִיכוּ יָמִים וְגוֹ׳. יָמִים הֶאֱרִיכוּ, שָׁנִים לֹא הֶאֱרִיכוּ, לְפִי שֶׁנִּתְעַצְּלוּ בְּהֶסְפֵּדוֹ, הוּא שֶׁנֶּאֱמַר (פסוק ט): הַר גָּעַשׁ, שֶׁרָעַשׁ עֲלֵיהֶם הָהָר לְהָרְגָן:",1,0],[2,9,"בְּתִמְנַת חֶרֶס. עַל שֵׁם שֶׁהֶעֱמִידוּ תְּמוּנַת חֶרֶס עַל קִבְרוֹ, כְּלוֹמַר חֲבָל עַל אָדָם שֶׁהֶעֱמִיד הַחַמָּה וּמוּטָל בְּקֶבֶר:",1,0],[2,15,"בְּכָל אֲשֶׁר יָצְאוּ יַד ה׳ הָיְתָה בָּם לְרָעָה. עַל אֲבִימֶלֶךְ וּמַחְלוֹן וְכִלְיוֹן נֶאֱמַר בְּ׳סֵדֶר עוֹלָם׳ (פרק יב):",1,0],[2,16,"וַיָּקֶם ה׳ שֹׁפְטִים. תָּמִיד מִדּוֹר אֶל דּוֹר, כְּמוֹ שֶׁהוּא מוֹנֶה וְהוֹלֵךְ בַּסֵּפֶר הַזֶּה, שׁוֹפֵט אַחַר שׁוֹפֵט:",1,0],[2,18,"וְכִי הֵקִים. לְשׁוֹן הֹוֶה, וְכַאֲשֶׁר הָיָה מֵקִים לָהֶם שׁוֹפְטִים, וְהָיָה ה׳ עִם הַשּׁוֹפֵט וְגוֹ׳:",1,0],[2,18,"כִּי יִנָּחֵם. שֶׁהָיָה מִתְנַחֵם לָהֶם עַל הָרָעָה, כֵּן תִּרְגֵּם יוֹנָתָן:",2,0],[2,18,"מִנַּאֲקָתָם. מִפְּנֵי נַאֲקָתָם, הָעוֹלָה לְפָנָיו מִפְּנֵי אוֹיְבֵיהֶם:",3,0],[2,19,"לֹא הִפִּילוּ. לֹא הִנִּיחוּ דָבָר לִהְיוֹת נוֹכָחִים עַל כָּל הַבָּא עֲלֵיהֶם:",1,0],[2,22,"הֲשֹׁמְרִים הֵם. ה״א חֲטַף פַּתַּח הוּא נָקוּד, לְפִי שֶׁהוּא לְשׁוֹן שְׁאֵלָה וְנִסָּיוֹן:",1,0],[3,1,"לְנַסּוֹת בָּם אֶת יִשְׂרָאֵל. אֶת דּוֹר הָאַחֵר אֲשֶׁר לֹא יָדְעוּ אֶת נִסֵּי מִלְחֲמוֹת כְּנַעַן וְלֹא רָאוּ אֶת הַמַּעֲשֶׂה הַגָּדוֹל, וְהִמְרוּ וּמָעֲלוּ בַמָּקוֹם:",1,0],[3,2,"רַק לְמַעַן דַּעַת. רַק לְדָבָר הַזֶּה לְבַדּוֹ הִנִּיחָם, לְמַעַן דַּעַת וּלְהִתְבּוֹנֵן דּוֹרוֹת בְּנֵי יִשְׂרָאֵל הַבָּאִים מַה הַחֵטְא גּוֹרֵם, כִּי עַתָּה הֵם זְקוּקִים לְלַמְּדָם מִלְחָמָה:",1,0],[3,2,"רַק אֲשֶׁר לְפָנִים. שֶׁהָיוּ עוֹמְדִים לְשָׁרֵת אֶת ה׳:",2,0],[3,2,"לֹא יְדָעוּם. לְמִלְחָמוֹת הַלָּלוּ וְטַכְסִיסֵיהֶם, וְלֹא נִצְרְכוּ לָהֶם:",3,0],[3,3,"חֲמֵשֶׁת סַרְנֵי פְלִשְׁתִּים. הֵם הַגּוֹיִם אֲשֶׁר הִנִּיחַ לְנַסּוֹת:",1,0],[3,10,"וַתְּהִי עָלָיו רוּחַ ה׳. דָּרַשׁ רַבִּי תַּנְחוּמָא (מדרש תנחומא שמות כ) נִסְתַּכֵּל בָּהֶם, שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה בְּמִצְרַיִם (שמות ג:ז) רָאֹה רָאִיתִי אֶת עֳנִי עַמִּי, מַה הֵן שְׁתֵּי רְאִיּוֹת הַלָּלוּ, אָמַר לוֹ: רוֹאֶה אֲנִי שֶׁעֲתִידִין לִטְעוֹת בָּעֵגֶל, וְאַף עַל פִּי כֵן ׳רָאִיתִי אֶת עֳנִי עַמִּי׳. זוֹ דָּרַשׁ עָתְנִיאֵל, אָמַר: בֵּין זַכִּים בֵּין חַיָּבִים, עָלָיו לְהוֹשִׁיעָם:",1,0],[3,13,"אֶת עִיר הַתְּמָרִים. יְרִיחוֹ:",1,0],[3,15,"אִטֵּר יַד יְמִינוֹ. תִּרְגֵּם יְהוֹנָתָן: גְּבַר גְּמִיד יַד יְמִינֵיהּ, וְכָל גְּמִיד לְשׁוֹן אֲרָמִי הוּא, דָּבָר כָּווּץ מֵחֲמַת חֹלִי, ריטרי״ט בְּלַעַ״ז; לֹא הָיָה שׁוֹלֵט בְּיַד יְמִינוֹ. וּבִלְשׁוֹן עִבְרִי: אִטֵּר, אָטוּם, כְּמוֹ (תהלים סט:טז) וְאַל תֶּאְטַר עָלַי בְּאֵר פִּיהָ, אָטוּם בְּיַד יְמִינוֹ, שֶׁלֹּא הָיָה שׁוֹלֵט בָּהּ:",1,0],[3,16,"גֹּמֶד אָרְכָּהּ. אַמָּה גְּדוּמָה, וּבִלְשׁוֹן אַשְׁכְּנַז: דוימ״ן לאנ״ג, וּבִלְשׁוֹן לַעַז: גשקור״ט:",1,0],[3,16,"עַל יֶרֶךְ יְמִינוֹ. לְפִי שֶׁבִּשְׂמֹאלוֹ שׁוֹלֵט, יֹאחֲזֶנָּה בִּשְׂמֹאלוֹ:",2,0],[3,17,"אִישׁ בָּרִיא. (תרגום:) פָּטִים:",1,0],[3,18,"וַיְשַׁלַּח אֶת הָעָם. חָזַר לַאֲחוֹרָיו וְלִוָּה אֶת חֲבוּרַת יִשְׂרָאֵל אֲשֶׁר בָּאוּ עִמּוֹ לָשֵׂאת אֶת הַמִּנְחָה, וְלִוָּה אוֹתָם עַד הַגִּלְגָּל:",1,0],[3,19,"וְהוּא שָׁב. יְחִידִי:",1,0],[3,19,"מִן הַפְּסִילִים. מָקוֹם שֶׁפּוֹסְלִים שָׁם אֲבָנִים מִן הָהָר, וְכֵן תִּרְגֵּם יוֹנָתָן: מִן מַחְצְבַיָּא, וּבָא אֶל עֶגְלוֹן וַיֹּאמֶר לוֹ:",2,0],[3,19,"וַיֹּאמֶר הָס. אָמַר עֶגְלוֹן: שִׁתְקוּ אֶת הַכֹּל מֵעָלַי, וְיוֹנָתָן תִּרְגֵּם הָס: סְלִיק, הוֹצִיא כָּל אִישׁ, וְאַף עַל פִּי כֵן ׳הָס׳, לְשׁוֹן שְׁתוֹק:",3,0],[3,20,"בַּעֲלִיַּת הַמְּקֵרָה. (תרגום:) בַּעֲלִיַּת בֵּית קַיְטָא, שֶׁהָיְתָה לָאֲוִיר וְצוֹנֶנֶת:",1,0],[3,20,"דְּבַר אֱלֹהִים לִי אֵלֶיךָ. וְצָרִיךְ אַתָּה לַעֲמוֹד:",2,0],[3,20,"וַיָּקָם מֵעַל הַכִּסֵּא. לְכָךְ זָכָה וְיָצְאָה מִמֶּנּוּ רוּת:",3,0],[3,22,"הַנִּצָּב. הוּא הַבַּרְזֶל שֶׁהַשָּׁנוּן תָּחוּב לְתוֹכוֹ, שֶׁקּוֹרִין הול״ט בְּלַעַ״ז, הוּא הַמַּעֲמִיד הַחֶרֶב עַל פִּי תַּעְרָהּ:",1,0],[3,22,"הַלַּהַב. הוּא הַשָּׁנוּן שֶׁקּוֹרִין ברונ״ט בְּלַעַ״ז, וּבְלַעַ״ז למ״א:",2,0],[3,22,"וַיִּסְגֹּר הַחֵלֶב. שֻׁמָּנוֹ, שֶׁהָיָה שָׁמֵן מְאֹד, וְכִסָּה אֶת כָּל אֹרֶךְ הַחֶרֶב:",3,0],[3,22,"וַיֵּצֵא הַפַּרְשְׁדֹּנָה. תִּרְגֵּם יוֹנָתָן: וּנְפַק אוּכְלֵיהּ שְׁפִיךְ, עֲשָׂאָן כִּשְׁתֵּי תֵבוֹת וְשִׁי״ן מְשַׁמֶּשֶׁת לִשְׁתֵּיהֶן, וַיֵּצֵא הַפֶּרֶשׁ, שְׁדוֹנָה, בִּשְׁפִיכָה. שָׁפַךְ, ׳שְׁדָא׳ כְּתַרְגּוּמוֹ:",4,0],[3,23,"וַיֵּצֵא אֵהוּד הַמִּסְדְּרוֹנָה. מִן הָעֲלִיָּה אֶל הַמִּסְדְּרוֹנָה, תִּרְגֵּם יוֹנָתָן: לְאַכְסַדְרָא:",1,0],[3,23,"וְנָעָל. בְּמַפְתֵּחַ:",2,0],[3,24,"וְהוּא יָצָא. אֵהוּד יָצָא, וְעַבְדָיו שֶׁל עֶגְלוֹן בָּאוּ:",1,0],[3,24,"מֵסִיךְ רַגְלָיו. (תרגום:) עָבֵיד צוֹרְכֵיהּ, הֵם נְקָבִים הַגְּדוֹלִים:",2,0],[3,25,"עַד בּוֹשׁ. עַד עִכּוּב, כְּלוֹמַר זְמַן אָרוֹךְ:",1,0],[3,26,"נִמְלַט. בָּרַח, אישקימוציי״ר בְּלַעַ״ז:",1,0],[3,26,"עַד הִתְמַהְמְהָם. כְּמוֹ (שיר השירים א:יב) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ, (שם ב:ז) אֶת הָאַהֲבָה עַד שֶׁתֶּחְפָּץ, בְּעוֹד שֶׁשְּׁנֵינוּ חֲפֵצִים בָּהּ:",2,0],[3,26,"הַשְּׂעִירָתָה. יַעַר דַּק וְעָב, שֶׁקּוֹרִין ברוצ״ש בְּלַעַ״ז, וְטוֹב הוּא לְהֵחָבֵא וְהַרְבֵּה יֵשׁ בְּסֵדֶר זְרָעִים שֶׁעַנְפֵי אִילָנוֹת דַּקִּים קְרוּיִין שֵׂעָר (כלאים ד:ט) הוֹפֵךְ אֶת הַשֵּׂעָר, (פאה ב:ג) וְאִם הָיָה הַשֵּׂעָר כּוֹתֵשׁ:",3,0],[3,27,"וַיְהִי בְּבוֹאוֹ. שֶׁעָבַר אֶת הַיַּרְדֵּן וּבָא לִמְקוֹמוֹ בְּאֶרֶץ כְּנָעַן:",1,0],[3,27,"בְּהַר אֶפְרָיִם. שֶׁהָיָה בְּאֶרֶץ כְּנַעַן בְּעֵבֶר הַיַּרְדֵּן הַמַּעֲרָבִי, וְאֶרֶץ מוֹאָב הָיְתָה בְּעֵבֶר הַיַּרְדֵּן בְּמִזְרָחוֹ, מִתּוֹךְ שֶׁשָּׁלְטוּ בְּיִשְׂרָאֵל וְעָבְרוּ אֶת הַיַּרְדֵּן, יָרְשׁוּ אֶת יְרִיחוֹ, כְּמוֹ שֶׁכָּתוּב לְמַעְלָה (פסוק יג) וְנָתְנוּ אֶת סַרְנֵיהֶם וּשְׁלִיטֵיהֶם עַל יִשְׂרָאֵל:",2,0],[3,28,"רִדְפוּ. לַהֲרֹג אֶת כָּל מוֹאָב שֶׁבְּעֵבֶר הַיַּרְדֵּן שֶׁלָּנוּ:",1,0],[3,28,"וַיִּלְכְּדוּ אֶת מַעְבְּרוֹת הַיַּרְדֵּן. שֶׁלֹּא יַעַבְרוּ מוֹאָב לָנוּס וְלָשׁוּב אֶל אַרְצָם:",2,0],[3,29,"כָּל שָׁמֵן. (תרגום:) כָּל גְּבַר אֵימְתָן:",1,0],[3,31,"מַלְמַד. הוּא דָּרְבָן, מַרְדֵּעַ, אגויילו״ן בְּלַעַ״ז:",1,0],[4,2,"בַּחֲרֹשֶׁת הַגּוֹיִם. שֵׁם עִיר, עַל שֵׁם שֶׁהָיְתָה חֲזָקָה וְשׁוֹלֶטֶת:",1,0],[4,3,"לָחַץ אֶת בְּנֵי יִשְׂרָאֵל בְּחָזְקָה. דָּרַשׁ רַבִּי תַּנְחוּמָא (צו ב): בְּגִדּוּפִין, וְכֵן הוּא אוֹמֵר (מלאכי ג:יג): חָזְקוּ עָלַי דִּבְרֵיכֶם:",1,0],[4,4,"אֵשֶׁת לַפִּידוֹת. שֶׁהָיְתָה עוֹשָׂה פְּתִילוֹת לַמִּקְדָּשׁ:",1,0],[4,5,"תַּחַת תֹּמֶר. תְּמָרִים הָיוּ לָהּ בִּירִיחוֹ:",1,0],[4,5,"בֵּין הָרָמָה וּבֵין בֵּית אֵל בְּהַר אֶפְרָיִם. לְפִי תַּרְגּוּמוֹ שֶׁל יוֹנָתָן יֵשׁ לִלְמֹד שֶׁאֵין מִקְרָא זֶה כְּמַשְׁמָעוֹ, וְאֵין אֵלּוּ סִימָנֵי מְקוֹם יְשִׁיבָתָהּ, אֶלָּא לָמַדְנוּ שֶׁאִשָּׁה עֲשִׁירָה הָיְתָה וּמִן הַמְּקוֹמוֹת הָאֵלּוּ הָיְתָה פַּרְנָסָתָהּ, וְהִיא יוֹשֶׁבֶת בְּעִירָהּ, עֲטָרוֹת שְׁמָהּ:",2,0],[4,5,"תַּחַת תֹּמֶר. תְּמָרִים הָיוּ לָהּ בִּירִיחוֹ, וּכְרָמִים בָּרָמָה, וְזֵיתִים בְּבִקְעַת בֵּית אֵל, שֶׁהוּא מְקוֹם שָׁמֵן, וְעָפָר חִוָּר בְּהַר אֶפְרַיִם, (תרגום:) ׳בְּטוּר מַלְכָּא׳, אוֹמֵר אֲנִי שֶׁמּוֹכְרִין אוֹתָהּ לְיוֹצְרֵי חֶרֶשׂ. וְיֵשׁ פּוֹתְרִין: ׳עָפָר חִוָּר׳, שְׂדֵה זֶרַע, כְּמוֹ (משנה שביעית ב:א): שְׂדֵה הַלָּבָן:",3,0],[4,6,"הֲלֹא צִוָּה. בְּיַד מֹשֶׁה (דברים כ:יז): כִּי הַחֲרֵם תַּחֲרִימֵם, כָּךְ שְׁנוּיָה בִּמְכִילְתָא (בא יב):",1,0],[4,10,"וַיַּעַל בְּרַגְלָיו. עִמּוֹ:",1,0],[4,11,"אֵלוֹן בְּצַעֲנַנִּים. (תרגום:) מֵישַׁר אַגְנַיָּא, מְקוֹם מֵישַׁר שֶׁל בְּצָעִים, מריש״ק בְּלַעַ״ז וְהוּא אַגְנַיָּא גֵּבִים, כְּמִין גּוּמוֹת שֶׁהַמַּיִם נִקְבָּצִים שָׁם, ׳אַגְנֵי דְּאַרְעָא מִקְרוֹן׳ (קידושין סא א):",1,0],[4,13,"מֵחֲרֹשֶׁת הַגּוֹיִם אֶל נַחַל קִישׁוֹן. הִזְעִיקָם שֶׁיֵּלְכוּ אֶל נַחַל קִישׁוֹן מֵחֲרֹשֶׁת הַגּוֹיִם שֶׁהוּא יוֹשֵׁב שָׁם:",1,0],[4,18,"בַּשְּׂמִיכָה. תִּרְגֵּם יוֹנָתָן: בְּגוֹנְכָא, וּפֵרַשׁ רַב הַאי (שבת נא א): גּוֹנְכָא - גְּלוּפְקְרִין, קוט״א בְּלַעַ״ז:",1,0],[4,19,"נֹאד הֶחָלָב. שֶׁהֶחָלָב מַכְבִּיד אֶת הַגּוּף לִהְיוֹת נִרְדָּם:",1,0],[4,20,"עֲמֹד פֶּתַח הָאֹהֶל. זָרְזִי עַצְמֵךְ כְּזָכָר. וְיֵשׁ פּוֹתְרִים: ׳עֲמֹד׳, כְּמוֹ לַעֲמֹד:",1,0],[4,21,"יְתַד הָאֹהֶל. קבילי״ל בְּלַעַ״ז, שֶׁתּוֹקְעִין בָּאָרֶץ עִם שִׁפּוּלֵי הָאֹהֶל לְפוֹשְׁטוֹ:",1,0],[4,21,"הַמַּקֶּבֶת. (תרגום:) אַרְזַפְתָּא, מרטי״ל בְּלַעַ״ז:",2,0],[4,21,"בַּלָּאט. (תרגום:) בְּרָז, חֶרֶשׁ:",3,0],[4,21,"וַתִּצְנַח בָּאָרֶץ. (תרגום:) וּנְעָצַת בְּאַרְעָא:",4,0],[4,22,"בְּרַקָּתוֹ. (תרגום:) בְּצִידְעֵיהּ, ניל״ה טימפי״ה בְּלַעַ״ז, וּתְחָבָהּ בְּרַקָּתוֹ וּבָאָרֶץ:",1,0],[5,2,"בִּפְרֹעַ פְּרָעוֹת בְּיִשְׂרָאֵל בְּהִתְנַדֵּב עָם. כְּשֶׁבָּאוּ פְּרָצוֹת עַל יִשְׂרָאֵל שֶׁפָּרְצוּ בָּהֶם אוֹיְבֵיהֶם עַל עָזְבָם אֶת ה׳, וְהִתְנַדֵּב הָעָם לָשׁוּב בִּתְשׁוּבָה, מֵעַתָּה בָּרְכוּ אֶת ה׳ עַל הַתְּשׁוּעוֹת שֶׁעָשָׂה:",1,0],[5,3,"אָנֹכִי אָנֹכִי. כָּפוּל, שָׁמַעְתִּי מִדְרַשׁ אַגָּדָה (ילקוט שמעוני ב מז) לֹא קִפֵּחַ הַקָּדוֹשׁ בָּרוּךְ הוּא שְׂכַר תָּבוֹר וְכַרְמֶל, שֶׁבָּאוּ לְמַתַּן תּוֹרָה לָתֵת עֲלֵיהֶם אֶת הַתּוֹרָה וְחָזְרוּ בְּבֹשֶׁת הַפָּנִים, אָמַר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, סוֹף שֶׁאֲנִי פּוֹרֵעַ לָכֶם כִּפְלַיִם, נֶאֱמַר בְּסִינַי (שמות כ:ב) אָנֹכִי ה׳ אֱלֹהֶיךָ, בְּתָבוֹר יֵאָמַר: אָנֹכִי אָנֹכִי. נֶאֱמַר בְּסִינַי (שם) אָנֹכִי ה׳ אֱלֹהֶיךָ, בְּכַרְמֶל יֵאָמַר, כָּפוּל (מלכים א יח:לט) ה׳ הוּא הָאֱלֹהִים, ה׳ הוּא הָאֱלֹהִים, בִּימֵי אֵלִיָּהוּ:",1,0],[5,4,"ה׳ בְּצֵאתְךָ מִשֵּׂעִיר. זֶה מַתַּן תּוֹרָה, כְּמָה שֶׁנֶּאֱמַר (דברים לג:ב) וְזָרַח מִשֵּׂעִיר לָמוֹ, וּמַה עִנְיָנָהּ לְכָאן, כָּךְ אָמְרָה דְּבוֹרָה: קָשָׁה הִיא הַתּוֹרָה לִפְרֹשׁ מִמֶּנָּה וְטוֹבָה הִיא לִדְבַּק בָּהּ, שֶׁהֲרֵי בְּמוֹרָא וּבִגְבוּרָה נִתְּנָה, וּלְכָךְ נִמְסְרוּ יִשְׂרָאֵל בְּיַד אוֹיְבֵיהֶם עַל פְּרִישָׁתָם הֵימֶנָּה וּכְשֶׁהִתְנַדְּבוּ לַעֲסוֹק בָּהּ נוֹשְׁעוּ, כָּל זֶה יֵשׁ לִלְמֹד מִתַּרְגּוּמוֹ שֶׁל יוֹנָתָן:",1,0],[5,4,"נָטְפוּ. הֵזִילוּ טַל תְּחִיָּה:",2,0],[5,5,"הָרִים נָזְלוּ. כְּמַיִם נוֹזְלִים נָמוֹגוּ:",1,0],[5,5,"זֶה סִינַי. כְּבָר מְפֹרָשׁ (שמות יט:כ) מַה נִרְאָה בּוֹ: עָשַׁן כֻּלּוֹ, וְקוֹל, וְלַפִּידִים וְאֵשׁ:",2,0],[5,5,"מִפְּנֵי ה׳. וַהֲרֵי זֶה מִקְרָא קָצָר ׳זֶה סִינַי׳, מַה אֵרַע בּוֹ, מִפְּנֵי אֲשֶׁר יָרַד עָלָיו ה׳:",3,0],[5,6,"בִּימֵי שַׁמְגַּר בֶּן עֲנָת בִּימֵי יָעֵל. מְלַמֵּד שֶׁאַף יָעֵל שָׁפְטָה אֶת יִשְׂרָאֵל בְּיָמֶיהָ:",1,0],[5,6,"חָדְלוּ אֳרָחוֹת. הָיוּ יְרֵאִים יִשְׂרָאֵל לָצֵאת לְדַרְכָּם מִפְּנֵי הָאוֹיְבִים וְהָיוּ הוֹלְכִים דֶּרֶךְ עֲקַלָּתוֹן בְּהֵחָבֵא:",2,0],[5,7,"חָדְלוּ פְרָזוֹן. עָרֵי הַפְּרָזִי שֶׁאֵין לָהֶם חוֹמָה חָדְלוּ מִהְיוֹת יוֹשְׁבִים בָּהֶם מִפְּנֵי אוֹיְבֵיהֶם, וְנֶאֶסְפוּ אֶל עָרֵי הַמִּבְצָר:",1,0],[5,7,"עַד שַׁקַּמְתִּי. כְּמוֹ שֶׁקַּמְתִּי, וְכֵן (שופטים ו:יז) שָׁאַתָּה מְדַבֵּר עִמִּי:",2,0],[5,8,"יִבְחַר אֱלֹהִים חֲדָשִׁים אָז לָחֶם שְׁעָרִים. כְּשֶׁבָּחַר לוֹ יִשְׂרָאֵל אֱלֹהִים חֲדָשִׁים, אָז הֻזְקְקוּ לְמִלְחָמָה בְּשַׁעֲרֵיהֶם, רְאוּ עַתָּה בְּהִתְנַדְּבָם, אִם יֵרָאֶה בְּיִשְׂרָאֵל מָגֵן וָרֹמַח, שֶׁצָּרִיךְ לְהִלָּחֵם בְּאַרְבָּעִים אֶלֶף רָאשֵׁי גְיָסוֹת שֶׁהֵבִיא הַגּוֹי עֲלֵיהֶם, וְכֻלָּם הֲמָמָם הַמָּקוֹם בְּמִלְחֶמֶת הַכּוֹכָבִים (פסוק כא) וְנַחַל קִישׁוֹן גְּרָפָם:",1,0],[5,8,"שְׁעָרִים. כְּמוֹ (דברים יז:ב) כִּי יִמָּצֵא בְקִרְבְּךָ בְּאַחַד שְׁעָרֶיךָ, עֲיָירוֹת:",2,0],[5,9,"לִבִּי. אֲנִי דְּבוֹרָה לְחוֹקְקֵי יִשְׂרָאֵל, לֶאֱהֹב אֶת חַכְמֵי יִשְׂרָאֵל שֶׁהִתְנַדְּבוּ בָּעָם, לֵאמֹר: בָּרְכוּ אֶת ה׳ וְשׁוּבוּ אֵלָיו:",1,0],[5,10,"רֹכְבֵי אֲתֹנוֹת צְחֹרוֹת. הַסּוֹחֲרִים וְהַשָּׂרִים שֶׁיִּרְכְּבוּ מֵעַתָּה עַל אֲתוֹנוֹת לְבָנוֹת הַחֲשׁוּבוֹת, מִבְּלִי יִרְאָה וְדַאֲגַת אוֹיְבֵיהֶם, וְאוֹתָן שֶׁיּוֹשְׁבִין עַל מִדִּין, לְשׁוֹן דַּיָּנִים, שֶׁהָיוּ יְרֵאִים לַעֲשׂוֹת מִשְׁפָּט בְּפַרְהֶסְיָא, וְכֵן תִּרְגֵּם יוֹנָתָן: דַּהֲווֹ מִתְחַבְּרִין לְמֵיתַב עַל דִּינָא, וְאוֹתָן שֶׁהוֹלְכִין רַגְלִי עַל דֶּרֶךְ, שִׂיחוּ וְסַפְּרוּ אֶת הַתְּשׁוּעָה הַזֹּאת, אֲשֶׁר מִקּוֹל הַמְחַצְּצִים אֶתְכֶם, אוֹרְבִים, לִסְטִים וּמוֹכְסִין, הַיּוֹשְׁבִין גְּדוּדִים בְּמַעֲרָכוֹת לֶאֱרֹב בְּעָבְרֵי הַמַּיִם, שָׁם יִתְּנוּ עַתָּה רוֹכְבֵי הָאֲתוֹנוֹת וְהוֹלְכֵי עַל דֶּרֶךְ אֶת צִדְקוֹת ה׳, וּמַה הֵן הַצְּדָקוֹת (פסוק יא) צִדְקוֹת פִּרְזוֹנוֹ בְּיִשְׂרָאֵל שֶׁהִשְׁקִיט אֶת יִשְׂרָאֵל, לִשְׁכּוֹן פְּרָזוֹן וְלָצֵאת מְפֻזָּרִים בִּיחִידִי, שֶׁלֹּא בַּאֲסִיפַת עָם:",1,0],[5,11,"מְחַצְצִים. פָּתַר מְנַחֵם: עוֹרְכֵי מִלְחָמָה וְסוֹדְרֵי קְרָב, וְחִבְּרוֹ עִם (משלי ל:כז) מֶלֶךְ אֵין לָאַרְבֶּה וַיֵּצֵא חֹצֵץ כֻּלּוֹ, לְשׁוֹן גְּדוּדִים. דָּבָר אַחֵר:",1,0],[5,11,"מִקּוֹל מְחַצְצִים בֵּין מַשְׁאַבִּים. כְּשֶׁהֱיִיתֶם הוֹלְכִים בֵּין מַשְׁאַבִּים לִשְׁאֹב מַיִם, הֱיִיתֶם יְרֵאִים מִקּוֹל אֲבָנִים, חַלּוּקֵי הַנַּחַל, קיזל״ש בְּלַעַ״ז, שֶׁהָעוֹבֵר עֲלֵיהֶם נִשְׁמָע קוֹלָם, וֶהֱיִיתֶם יְרֵאִים שֶׁלֹּא יַרְגִּישׁוּ בָכֶם אוֹיְבֵיכֶם, מֵעַכְשָׁיו אֵין לָחוּשׁ עַל זֹאת, וּמִשּׁוּם הָכִי מִצְוָה עֲלֵיכֶם לִיתֵּן הוֹדָיָה לִשְׁמוֹ:",2,0],[5,11,"מְחַצְצִים. לְשׁוֹן אַבְנֵי חִלּוּקֵי הַנַּחַל, כְּמוֹ (איכה ג:טז): ״וַיַּגְרֵס בֶּחָצָץ״:",3,0],[5,11,"אָז יָרְדוּ לַשְּׁעָרִים. חָזְרוּ לְעָרֵי מוֹשְׁבוֹתָם שֶׁבָּרְחוּ מֵהֶם לֵיאָסֵף אֶל עָרֵי הַמִּבְצָר:",4,0],[5,12,"עוּרִי עוּרִי דְּבוֹרָה. לְשׁוֹן שֶׁבַח כִּפְשׁוּטוֹ, הִתְגַּבְּרִי בְּשִׁירָתֵךְ וְרַבּוֹתֵינוּ אָמְרוּ (פסחים סו:) מִפְּנֵי שֶׁנִּתְהַלְּלָה וְאָמְרָה (פסוק ז) עַד שַׁקַּמְתִּי דְּבוֹרָה, נִסְתַּלְּקָה הֵימֶנָּה רוּחַ הַקֹּדֶשׁ:",1,0],[5,13,"אָז יָרַד שָׂרִיד לְאַדִּירִים. יָרַד - יִרְדֶּה, כְּמוֹ (ישעיהו מה:א) לְרַד לְפָנָיו גוֹיִם, שְׂרִידֵי יִשְׂרָאֵל רָדוּ בְּאַדִּירֵי הַגּוֹיִם:",1,0],[5,13,"ה׳ יְרַד לִי בַּגִּבּוֹרִים. יִרְדֶּה לִי אֶת גִּבּוֹרֵי הַגּוֹיִם:",2,0],[5,14,"מִנִּי אֶפְרַיִם. מִן אֶפְרַיִם יָצָא שׁוֹרֶשׁ יְהוֹשֻׁעַ בֶּן נוּן, לִרְדּוֹת בַּעֲמָלֵק לַחֲלֹשׁ אוֹתוֹ לְפִי חֶרֶב, וּמְחֻבָּר מִקְרָא זֶה לְעֶלְיוֹן, לְפָרֵשׁ: ה׳ יְרַד לִי בַּגִּבּוֹרִים, אֶת יְהוֹשֻׁעַ הֵקִים לְרַד בַּעֲמָלֵק:",1,0],[5,14,"אַחֲרֶיךָ. יָקוּם מִשֵּׁבֶט בִּנְיָמִין שָׁאוּל בֶּן קִישׁ שֶׁיִּגְרְמֶנּוּ וִיעַמֵּם אוֹתוֹ כְּגֶחָלִים עוֹמְמוֹת וְיֵשׁ לִפְתּוֹר: ״בַּעֲמָמֶיךָ״, בְּחַיִל שֶׁל מָאתַיִם אֶלֶף רַגְלִי שֶׁבָּא שָׁאוּל עֲלֵיהֶם:",2,0],[5,14,"מִנִּי מָכִיר יָרְדוּ מְחֹקְקִים. שָׂרִים גְּדוֹלִים שֶׁכָּבְשׁוּ אֶת הָאֱמוֹרִי, אֲשֶׁר כָּבְשׁוּ (דברים ג:ד) שִׁשִּׁים עִיר כָּל חֶבֶל אַרְגּוֹב שֶׁכָּבַשׁ יָאִיר:",3,0],[5,15,"וְשָׂרַי בְּיִשָּׂשכָר. שָׂרִים שֶׁבְּיִשָּׂשכָר, הֵם סַנְהֶדְרָאוֹת עוֹסְקִין בַּתּוֹרָה, (דברי הימים א יב:לג) יוֹדְעֵי בִינָה לָעִתִּים, הֵם תָּמִיד עִם דְּבוֹרָה לְלַמֵּד בְּיִשְׂרָאֵל חֹק וּמִשְׁפָּט:",1,0],[5,15,"וְשָׂרַי בְּיִשָּׂשכָר. יוּ״ד זוֹ טְפֵלָה הִיא וְאֵינָהּ מְשַׁמֶּשֶׁת כְּלוּם, וַהֲרֵי הִיא כְּיוּ״ד (תהלים ח:ח) בַּהֲמוֹת שָׂדַי, (ירמיהו כב:יד) וְקָרַע לוֹ חַלּוֹנָי:",2,0],[5,15,"וְיִשָּׂשכָר כֵּן בָּרָק. וּשְׁאָר הָעָם שֶׁל יִשָּׂשכָר, כֵּן הֵם עִם בָּרָק לְכָל אֲשֶׁר יְצַוֶּה:",3,0],[5,15,"בָּעֵמֶק שֻׁלַּח בְּרַגְלָיו. שְׁלָחָם בְּכָל שְׁלִיחוּתוֹ, וְלֶאֱסוֹף אֶת הָעָם וּלְכָל צָרְכֵי הַמִּלְחָמָה:",4,0],[5,15,"בִּפְלַגּוֹת רְאוּבֵן. אֲבָל בְּחִלּוּקֵי לִבּוֹ שֶׁל רְאוּבֵן רַבּוּ חִקְקֵי לֵב. (תרגום:) נִכְלֵי לִיבָּא, עָרְמוּמִית, וּמָה הִיא עָרְמוּמִיתוֹ, יָשַׁב לוֹ בֵּין מִשְׁפְּתֵי הַמִּלְחָמָה לִשְׁמוֹעַ מִי נוֹצֵחַ וְיִהְיֶה עִמּוֹ:",5,0],[5,16,"שְׁרִיקוֹת עֲדָרִים. לִשְׁמוֹעַ קוֹל עֶדְרֵי הַמִּלְחָמָה, לְמִי קוֹל עֲנוֹת גְּבוּרָה וּלְמִי קוֹל עֲנוֹת חֲלוּשָׁה:",1,0],[5,17,"בְּעֵבֶר הַיַּרְדֵּן שָׁכֵן. וְלֹא בָא אֶל הַמִּלְחָמָה, וְכֵן דָּן הִכְנִיס מָמוֹנוֹ בִּסְפִינוֹת לַעֲמוֹד וְלִבְרוֹחַ:",1,0],[5,17,"וְעַל מִפְרָצָיו. לִשְׁמוֹר פִּרְצוֹת אַרְצוֹ:",2,0],[5,18,"זְבֻלוּן עַם חֵרֵף וְגוֹ׳. בִּזָּה נַפְשׁוֹ וְהִפְקִיר עַצְמוֹ לָמוּת בַּמִּלְחָמָה עִם בָּרָק, וְכֵן נַפְתָּלִי עַל מְרוֹמֵי שָׂדֶה עַל הַר תָּבוֹר:",1,0],[5,19,"בְּתַעְנַךְ עַל מֵי מְגִדּוֹ. תִּרְגֵּם יוֹנָתָן: בְּתַעֲנַךְ הֲווֹ שָׁרָן וּמָטָן עַל מֵי מְגִדּוֹ, רֹאשׁ הַמַּחֲנֶה בְּתַעֲנַךְ וּמַגִּיעַ עַד מֵי מְגִדּוֹ:",1,0],[5,19,"בֶּצַע כֶּסֶף לֹא לָקָחוּ. חִנָּם בָּאוּ לְעֶזְרַת סִיסְרָא, לֹא בִּקְשׁוּ מִמֶּנּוּ שָׂכָר:",2,0],[5,20,"מִן שָׁמַיִם נִלְחָמוּ. וְאַף הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח בָּם צְבָאָיו שֶׁאֵינָם רוֹצִים שׁוּם שָׂכָר:",1,0],[5,20,"מִמְּסִלּוֹתָם. רֹאשׁ הַכּוֹכָב בַּשָּׁמַיִם וְסוֹפוֹ בָּאָרֶץ, מִכָּאן אָמְרוּ (תנחומא בראשית ה) עָבְיוֹ שֶׁל רָקִיעַ כַּאֲוִיר שֶׁבֵּין שָׁמַיִם לָאָרֶץ, שֶׁהַכּוֹכָב תָּקוּעַ בָּרָקִיעַ כְּמִין נֶגֶר בְּדֶלֶת, מִדַּת אָרְכּוֹ כְּעָבְיוֹ שֶׁל רָקִיעַ, וּמִן הַמִּקְרָא שֶׁמֵּעִיד ׳מִמְּסִלּוֹתָם נִלְחָמוּ׳, אָנוּ שׁוֹמְעִין שֶׁעָבְיוֹ שֶׁל רָקִיעַ כְּגוֹבַהּ שָׁמַיִם מִן הָאָרֶץ:",2,0],[5,21,"גְּרָפָם. טֵאטֵם מִן הָעוֹלָם, כְּמַגְרֵפָה זוֹ שֶׁגּוֹרֶפֶת אֶת הָאֵפֶר מִן הַכִּירָה:",1,0],[5,21,"נַחַל קְדוּמִים. שֶׁנַּעֲשָׂה עָרֵב לַיָּם עַל זֶה מִימוֹת מִצְרַיִם, כִּדְאִיתָא בִּפְסָחִים (קיח:):",2,0],[5,21,"תִּדְרְכִי נַפְשִׁי. בָּרַגְלַיִם אֶת עֹז גִּבּוֹרֵי כְנָעַן:",3,0],[5,22,"הָלְמוּ עִקְּבֵי סוּס. נִשְׁתַּלְּפוּ טַלְפֵי סוּסֵיהֶם, שֶׁהָיָה חֹם הַכּוֹכָב מַרְתִּיחַ אֶת הַטִּיט וְהַצִּפּוֹרֶן נִשְׁמְטָה, כְּמוֹ שֶׁמּוֹלְגִין אֶת הָרַגְלַיִם בְּרוֹתְחִין וְהַטְּלָפִים נִשְׁמָטִים, מִתּוֹךְ שֶׁנִּשְׁתַּלְּפוּ נֶהֶלְמוּ הָרַגְלַיִם:",1,0],[5,22,"מִדַּהֲרוֹת דַּהֲרוֹת אַבִּירָיו. שֶׁהָיוּ מַרְקִידִים אֶת סוּסֵיהֶם בַּמִּלְחָמָה, כְּמוֹ (נחום ג:ב) וְסוּס דֹּהֵר, הוּא לְשׁוֹן הַרְקָדַת הַסּוּס:",2,0],[5,23,"אוֹרוּ מֵרוֹז. אָמְרֵי לַהּ כּוֹכְבָא הֲוָה, וְאָמְרֵי לַהּ גַּבְרָא חֲשִׁיבָא הֲוָה (מועד קטן טז.), וְהָיָה סָמוּךְ לִמְקוֹם הַמִּלְחָמָה וְלֹא בָא:",1,0],[5,23,"אָמַר מַלְאַךְ ה׳. אָמַר בָּרָק בִּשְׁלִיחוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא:",2,0],[5,23,"יוֹשְׁבֶיהָ. הַיּוֹשְׁבִים בְּאַרְבַּע אַמּוֹת שֶׁלּוֹ (שם) בְּאַרְבַּע מְאָה שִׁיפּוּרֵי שַׁמְּתֵיהּ בָּרָק לְמֵרוֹז:",3,0],[5,23,"לְעֶזְרַת ה׳. כִּבְיָכוֹל, שֶׁמִּי שֶׁהוּא עוֹזֵר אֶת יִשְׂרָאֵל, כְּעוֹזֵר אֶת הַשְּׁכִינָה:",4,0],[5,24,"מִנָּשִׁים בָּאֹהֶל. שָׂרָה, שֶׁנֶּאֱמַר בָּהּ (בראשית יח:ט) הִנֵּה בָאֹהֶל. רִבְקָה שֶׁנֶּאֱמַר בָּהּ (בראשית כד:סז) וַיְבִיאֶהָ יִצְחָק הָאֹהֱלָה. רָחֵל וְלֵאָה, שֶׁנֶּאֱמַר בָּהֶן (בראשית לא:לג) וַיֵּצֵא מֵאֹהֶל לֵאָה וְגוֹ׳:",1,0],[5,24,"מִנָּשִׁים בָּאֹהֶל תְּבֹרָךְ. יָעֵל לָמָּה - הֵן יָלְדוּ וְגִדְּלוּ, וְאִם לֹא יָעֵל הֲרֵי הָרָשָׁע הַזֶּה בָּא וּמְאַבְּדָן, כָּךְ הוּא בִּבְרֵאשִׁית רַבָּה (מח:טו). דָּבָר אַחֵר, אַף יָעֵל הָיְתָה יוֹשֶׁבֶת אֹהָלִים, לְפִיכָךְ הִזְכִּיר אוֹתָהּ בְּבִרְכַּת אֹהָלִים:",2,0],[5,25,"חָלָב נָתָנָה. לָדַעַת אִם לִבּוֹ עָלָיו שֶׁיָּבִין בֵּין טַעַם מַיִם לְטַעַם חָלָב, כֵּן תִּרְגֵּם יוֹנָתָן:",1,0],[5,25,"בְּסֵפֶל אַדִּירִים. בְּסֵפֶל שֶׁשּׁוֹתִין בּוֹ מַיִם, שֶׁהַמַּיִם נִקְרְאוּ ׳אַדִּירִים׳, שֶׁנֶּאֱמַר (שמות טו:י): בְּמַיִם אַדִּירִים:",2,0],[5,26,"לְהַלְמוּת עֲמֵלִים. סִיסְרָא, שֶׁהָיָה עָמֵל וְיָגֵעַ:",1,0],[5,26,"מָחֲקָה. לְשׁוֹן חִיקּוּי:",2,0],[5,26,"וּמָחֲצָה. לְשׁוֹן מַחַץ:",3,0],[5,26,"וְחָלְפָה. יוֹצֵא מִצַּד אַחֵר:",4,0],[5,28,"וַתְּיַבֵּב. לְשׁוֹן דִּבּוּר, כְּמוֹ (ישעיהו נז:יט) נִיב שְׂפָתַיִם וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ (ראש השנה לג:) לְשׁוֹן גְּנִיחָה, כִּתְרוּעָה, דִּמְתַרְגְּמִינָן ׳יְבָבָא׳ (ויקרא כג:כד). וַאֲנִי אוֹמֵר: לְשׁוֹן רְאִיָּה, כְּמוֹ (זכריה ב:ב) בָּבַת עֵינִי, וְכֵן חִבְּרוֹ מְנַחֵם:",1,0],[5,28,"אֶשְׁנָב. חַלּוֹן:",2,0],[5,29,"חַכְמוֹת שָׂרוֹתֶיהָ תַּעֲנֶינָה. הַחֲכָמוֹת שֶׁבְּשָׂרוֹתֶיהָ, לְכָךְ נָקוּד חֵי״ת פַּתַּ״ח, חָכְמוֹת שֶׁהוּא שֵׁם דָּבָר נָקוּד חֲטַ״ף קָמַ״ץ, כְּמוֹ (משלי יד:א) רָאמוֹת לֶאֱוִיל חָכְמוֹת, וְזֶה נָקוּד חַכְמוֹת, וְכֵן (שם יד:א) חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ, חַכְמוֹת שֶׁבַּנָּשִׁים:",1,0],[5,29,"תַּעֲנֶינָּה. דַּגְשׁוּת שֶׁל נוּ״ן מְשַׁמֶּשֶׁת בִּמְקוֹם נוּ״ן שְׁלִישִׁית, וּפִתְרוֹנוֹ תַּעֲנֶינָּה אוֹתָהּ, דַּגְשׁוּת נוּ״ן מְשַׁמֶּשֶׁת בִּמְקוֹם ׳אוֹתָהּ׳, כְּמוֹ (ויקרא ו:יד) מֻרְבֶּכֶת תְּבִיאֶנָּה:",2,0],[5,29,"אַף הִיא תָּשִׁיב אֲמָרֶיהָ. תַּנְחוּמִין לְעַצְמָהּ: מָה אֲנִי מִתְמַהּ תְּמִיהָ עַל עִכּוּב בְּנִי:",3,0],[5,30,"הֲלֹא יִמְצְאוּ יְחַלְּקוּ שָׁלָל. וְהוּא מְעַכְּבָן:",1,0],[5,30,"רַחֲמָתַיִם לְרֹאשׁ גֶּבֶר. מְעַנִּים נָשִׁים יָפוֹת בְּיִשְׂרָאֵל, וְכָל אִישׁ מֵהֶם יֵשׁ לוֹ בְּמִטָּתוֹ שְׁתַּיִם וְשָׁלֹשׁ נָשִׁים:",2,0],[5,31,"כֵּן יֹאבְדוּ. דְּבוֹרָה אָמְרָה: תַּנְחוּמִין שֶׁל הֶבֶל הֵן לָהּ, כֵּן יֹאבְדוּ כָל אוֹיְבֶיךָ ה׳, כַּאֲשֶׁר אָבַד הוּא:",1,0],[5,31,"וְאֹהֲבָיו כְּצֵאת הַשֶּׁמֶשׁ בִּגְבוּרָתוֹ. לֶעָתִיד לָבֹא, (ישעיהו ל:כו) שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים, שֶׁהִיא עַל אַחַת שְׁלֹשׁ מֵאוֹת וְאַרְבָּעִים וְשָׁלֹשׁ כְּמִסְפַּר אַרְבָּעִים וְתֵשַׁע שְׁבִיעִיּוֹת:",2,0],[5,31,"וַתִּשְׁקֹט הָאָרֶץ. אֵין זֶה מִדִּבְרֵי דְבוֹרָה אֶלָּא מִדִּבְרֵי כּוֹתֵב הַסֵּפֶר:",3,0],[6,1,"וַיַּעֲשׂוּ הָרַע. עַד כָּאן נֶאֱמַר ׳וַיּוֹסִיפוּ׳, שֶׁהָיָה נִצְבָּר חֵטְא עַל חֵטְא, אֲבָל בְּשִׁירָה זוֹ נִמְחַל לָהֶם כָּל אֲשֶׁר עָשׂוּ, וְעַכְשָׁיו מַתְחִילִין לַחֲטוֹא, כָּךְ נִדְרַשׁ בְּאַגָּדַת תְּהִלִּים (מדרש תהלים יח ו):",1,0],[6,2,"הַמִּנְהָרוֹת. (תרגום:) מַטְמוֹרִיתָא, וּבִלְשׁוֹן לַעַ״ז: וודו״ש, וְעַל שֵׁם שֶׁעוֹשִׂין בָּהֶם מָאוֹר קָטָן בְּמָקוֹם שֶׁאֵין נִיכָּר קוֹרְאָן מִנְהָרוֹת, לויישיט״ש בְּלַעַ״ז:",1,0],[6,2,"מְעָרוֹת. גרוטי״ה בְּלַעַ״ז:",2,0],[6,2,"מְצָדוֹת. פליישדי״ץ בְּלַעַ״ז, שֶׁעוֹשִׂים בַּיְּעָרִים עַל יְדֵי הַפָּלַת הָאִילָנוֹת סָבִיב סָבִיב:",3,0],[6,5,"הֵם וּמִקְנֵיהֶם. לִרְעוֹת אֶת הַתְּבוּאָה:",1,0],[6,8,"אִישׁ נָבִיא. זֶה הַנָּבִיא הוּא פִּנְחָס, בְּ״סֵדֶר עוֹלָם״ (פרק ב):",1,0],[6,11,"אֲבִי הָעֶזְרִי. מִבְּנֵי אֲבִיעֶזֶר בֶּן גִּלְעָד בֶּן מְנַשֶּׁה:",1,0],[6,11,"וְגִדְעוֹן בְּנוֹ. אָבִיו הָיָה חוֹבְטָן וְהוּא כוֹבְרָן, אָמַר לוֹ: אַבָּא, זָקֵן אַתָּה וְאִם יָבֹאוּ הַמִּדְיָנִים לֹא תוּכַל לָנוּס, לֵךְ אַתָּה וַאֲנִי אֶחְבֹּט:",2,0],[6,11,"בַּגַּת. בְּקוֹרוֹת בֵּית הַבַּד:",3,0],[6,12,"ה׳ עִמְּךָ גִּבּוֹר הֶחָיִל. שֶׁנָּתַן לְךָ כֹּחַ כָּזֶה:",1,0],[6,13,"וְיֵשׁ ה׳ עִמָּנוּ. וְאִם יֵשׁ ה׳ עִמָּנוּ, לָמָּה מְצָאַתְנוּ וְגוֹ׳:",1,0],[6,13,"אֲשֶׁר סִפְּרוּ לָנוּ אֲבוֹתֵינוּ. פֶּסַח הָיָה, אָמַר לוֹ: אֶמֶשׁ הִקְרַנִי אַבָּא אֶת הַהַלֵּל, וּשְׁמַעְתִּיו שֶׁהָיָה אוֹמֵר (תהלים קיד:א): בְּצֵאת יִשְׂרָאֵל מִמִּצְרַיִם, ׳וְעַתָּה נְטָשָׁנוּ׳, אִם צַדִּיקִים הָיוּ אֲבוֹתֵינוּ, יַעֲשֶׂה לָנוּ בִּזְכוּתָם, וְאִם רְשָׁעִים הָיוּ, כְּשֵׁם שֶׁעָשָׂה לָהֶם נִפְלְאוֹתָיו חִנָּם כֵּן יַעֲשֶׂה לָנוּ, וְאַיֵּה כָל נִפְלְאוֹתָיו:",2,0],[6,14,"וַיִּפֶן אֵלָיו. הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעַצְמוֹ:",1,0],[6,14,"בְּכֹחֲךָ זֶה. בְּכֹחַ הַזְּכוּת הַזֶּה שֶׁלִּמַּדְתָּ סָנֵגוֹרְיָא עַל בָּנַי, כָּךְ דָּרַשׁ רַבִּי תַּנְחוּמָא (מדרש תנחומא שופטים ד):",2,0],[6,15,"הִנֵּה אַלְפִּי. הָאֶלֶף שֶׁאֲנִי נִמְנֶה בּוֹ לִהְיוֹת תַּחַת שַׂר הָאֶלֶף, הוּא הָאֶלֶף הַדַּל בְּכָל אַלְפֵי מְנַשֶּׁה:",1,0],[6,17,"שָׁאַתָּה. כְּמוֹ שֶׁאַתָּה:",1,0],[6,19,"קֶמַח מַצּוֹת. לָמַדְנוּ שֶׁפֶּסַח הָיָה, יוֹם תְּנוּפַת הָעוֹמֶר, לְכָךְ נֶאֱמַר (לקמן ז:יג) וְהִנֵּה צְלִיל לֶחֶם שְׂעוֹרִים מִתְהַפֵּךְ וְגוֹ׳:",1,0],[6,19,"וְהַמָּרַק. וְהָרוֹטֶב:",2,0],[6,22,"אֲהָהּ. לְשׁוֹן דְּאָגָה, כְּלוֹמַר מַה תְּהֵא עָלַי:",1,0],[6,22,"כִּי עַל כֵּן רָאִיתִי. כִּי עַל אֲשֶׁר רָאִיתִי מַלְאַךְ ה׳, לְכָךְ אֲנִי דּוֹאֵג וְצוֹעֵק ׳אֲהָהּ׳:",2,0],[6,24,"וַיִּקְרָא לוֹ. גִּדְעוֹן לַמִּזְבֵּחַ:",1,0],[6,24,"ה׳ שָׁלוֹם. ה׳ הוּא שְׁלוֹמֵנוּ:",2,0],[6,25,"פַּר הַשּׁוֹר. פַּר הַבָּחוּר, שֶׁהַשּׁוֹר בֶּן יוֹמוֹ קָרוּי שׁוֹר:",1,0],[6,25,"וּפַר הַשֵּׁנִי. (תרגום:) וְתוֹרָא תִּנְיָנָא:",2,0],[6,25,"שֶׁבַע שָׁנִים. (תרגום:) דְּאִיתְפַּטַּם שֶׁבַע שְׁנִין לַעֲבוֹדָה זָרָה. שְׁמוֹנָה דְבָרִים הוּתְרוּ אוֹתוֹ הַלַּיְלָה: מוּקְצֶה, אֲשֵׁרָה, וְלַיְלָה, וּבָמָה וְכוּ׳, כִּדְאִיתָא בִּתְמוּרָה (כח ב):",3,0],[6,26,"רֹאשׁ הַמָּעוֹז. רֹאשׁ הַסֶּלַע:",1,0],[6,31,"הַאַתֶּם תְּרִיבוּן לַבַּעַל. בִּשְׁבִיל הַבַּעַל:",1,0],[6,31,"תּוֹשִׁיעוּן אוֹתוֹ. תִּנְקְמוּ נִקְמָתוֹ, וְכֵן (שמואל א כה:לג): וְהֹשֵׁעַ יָדִי לִי, דְּדָוִד בְּנָבָל:",2,0],[6,31,"אֲשֶׁר יָרִיב לוֹ. בִּשְׁבִילוֹ:",3,0],[6,31,"עַד הַבֹּקֶר. עַד הַבֹּקֶר הַמְתִּינוּ:",4,0],[6,31,"אִם אֱלֹהִים הוּא. יָרִיב הוּא לְעַצְמוֹ רִיבוֹ וְנִקְמָתוֹ, וּכְדֵי לִדְחוֹתָם עַד שֶׁיִּבְרַח גִּדְעוֹן הָיָה אוֹמֵר כֵּן:",5,0],[6,32,"יָרֶב בּוֹ. בְּגִדְעוֹן. אֵצֶל רִיב נוֹפֵל עִם, אוֹ אֶת, אוֹ בּוֹ, כְּמוֹ (בראשית לא:לו): וַיָּרֶב בְּלָבָן, אֲבָל ׳לוֹ׳ אֵינוֹ נוֹפֵל עַל הַלָּשׁוֹן, וְכָל ׳לוֹ׳ הַכְּתוּבִים כָּאן ׳בִּשְׁבִיל׳ הֵם:",1,0],[6,34,"רוּחַ ה׳. רוּחַ גְּבוּרָה:",1,0],[6,34,"וַיִּזָּעֵק אֲבִיעֶזֶר. כָּל הַמִּשְׁפָּחָה:",2,0],[6,38,"וַיְהִי כֵן. שֶׁהָיָה טַל עַל הַגִּזָּה לְבַדָּהּ יוֹתֵר מִבִּשְׁאָר מְקוֹמוֹת, כְּמוֹ שֶׁהוּא אוֹמֵר (פסוק לז): מְלֹא הַסֵּפֶל מַיִם, אֲבָל ׳עַל כָּל הָאָרֶץ חֹרֶב׳ לֹא נִתְקַיֵּם, שֶׁהַבְּרִית כְּרוּתָה לַטַּל שֶׁאֵינוֹ נֶעְצָר (תענית ג א):",1,0],[6,38,"וַיָּזַר. לְשׁוֹן מְכַבֵּשׁ, וְכֵן (ישעיהו א:ו): לֹא זֹרוּ וְלֹא חֻבָּשׁוּ, לֹא נֶחְבְּשׁוּ לְהוֹצִיא הַלֵּחָה:",2,0],[7,1,"מִגִּבְעַת הַמּוֹרֶה בָּעֵמֶק. (תרגום:) דְּמִסְתַּכְּיָא לְמֵישְׁרָא. הַמּוֹרֶה, לְשׁוֹן הוֹרָאָה וּרְאִיָּה, כְּמוֹ (משלי ו:יג) מוֹרֶה בְּאֶצְבְּעוֹתָיו, שֶׁמִּשָּׁם צוֹפִים וְרוֹמְזִים בָּעֵמֶק:",1,0],[7,2,"יִתְפָּאֵר. וונטי״ר בְּלַעַ״ז:",1,0],[7,3,"וַיִּצְפֹּר. בַּבֹּקֶר, לְשׁוֹן אֲרָמִי: צַפְרָא:",1,0],[7,5,"כֹּל אֲשֶׁר יָלֹק בִּלְשׁוֹנוֹ וְגוֹ׳ וְכֹל אֲשֶׁר יִכְרַע עַל בִּרְכָּיו לִשְׁתּוֹת. תַּצִּיג אוֹתוֹ לְבַד חוּץ מִסִּיעָתְךָ, כִּי הֵם לֹא יֵלְכוּ עִמְּךָ, שֶׁכָּךְ הֵם לְמוּדִים לִכְרוֹעַ לִפְנֵי עֲבוֹדַת גִּלּוּלִים:",1,0],[7,6,"הַמְלַקְקִים בְּיָדָם. אֵין זֶה דֶּרֶךְ כְּרִיעָה כְּלוֹקֵק בִּלְשׁוֹנוֹ:",1,0],[7,12,"נֹפְלִים בָּעֵמֶק. שׁוֹכְנִים בָּעֵמֶק:",1,0],[7,13,"צְלִיל. צָלוּל כְּתִיב, שֶׁהָיָה הַדּוֹר צָלוּל מִן הַצַּדִּיקִים:",1,0],[7,13,"צְלִיל לֶחֶם שְׂעֹרִים. (תרגום:) חֲרַר דְּלֶחֶם שְׂעוֹרִים, חֲרָרָה שֶׁאוֹפִין עַל הַגֶּחָלִים:",2,0],[7,13,"לֶחֶם שְׂעֹרִים. הוּא זְכוּת הָעוֹמֶר הַקָּרֵב בְּפֶסַח:",3,0],[7,13,"וַיַּכֵּהוּ וַיִּפֹּל. הָאֹהֶל: וַיַּהַפְכֵהוּ. הָאֹהֶל מִלְּמַטָּה לְמַעְלָה, וְנָפַל הָאֹהֶל:",4,0],[7,15,"אֶת מִסְפַּר הַחֲלוֹם. אֶת סִפּוּר הַחֲלוֹם, (תרגום:) יַת שׁוּעִית חֶלְמָא וְיַת פִּשְׁרֵיהּ:",1,0],[7,15,"וְאֶת שִׁבְרוֹ. וְאֶת מִמְכָּרוֹ, כְּלוֹמַר: וְאֶת פִּתְרוֹנוֹ:",2,0],[7,16,"שׁוֹפָרוֹת וְלַפִּידִים. לְהַזְכִּיר זְכוּת מַתַּן תּוֹרָה וּפְשׁוּטוֹ: לַיְלָה הָיָה, כְּמוֹ שֶׁכָּתוּב (פסוק ט) וְהָיָה חֹשֶׁךְ, לְפִיכָךְ נָשְׂאוּ שָׁם לַפִּידִים לְהָאִיר לָהֶם וּנְתָנוּם בַּכַּדִּים כְּדֵי שֶׁלֹּא יָבִינוּ בַּלַּפִּידִים:",1,0],[7,17,"מִמֶּנִּי תִרְאוּ. אֶת אֲשֶׁר אֲנִי עוֹשֶׂה, רְאוּ וַעֲשׂוּ כֵן:",1,0],[7,18,"אָנֹכִי וְכָל אֲשֶׁר אִתִּי. אֶחָד מִן הָרָאשִׁים, וּמֵאָה אִישׁ הָיָה עִמּוֹ (פסוק יט):",1,0],[7,18,"לַה׳ וּלְגִדְעוֹן. (תרגום:) חַרְבָּא דִּמְקַטְּלָא מִן קֳדָם ה׳ וְנִצְחָנָא עַל יְדֵי גִדְעוֹן:",2,0],[7,19,"הָקֵם הֵקִימוּ. כְּבָר בְּנֵי הַחַיִל אֶת הַשּׁוֹמְרִים שֶׁהָיְתָה מִשְׁמַרְתָּם בָּאַשְׁמֹרֶת הַתִּיכוֹנָה, שֶׁכֵּן דֶּרֶךְ בְּנֵי גְיָיסוֹת לְהַעֲמִיד שׁוֹמְרִים, אֵלּוּ יִשְׁמְרוּ שְׁלִישׁ הַלַּיְלָה הָרִאשׁוֹן וְאֵלּוּ שְׁלִישׁ הַשֵּׁנִי, וְאֵלּוּ שְׁלִישׁ הָאַחֲרוֹן:",1,0],[7,19,"וְנָפוֹץ הַכַּדִּים. וְלִשְׁבּוֹר הַכַּדִּים אֲשֶׁר בְּיָדָם:",2,0],[7,21,"וַיָּרִיעוּ. תְּרוּעַת מַסָּע וְנִיסָה:",1,0],[7,24,"וְלִכְדוּ לָהֶם אֶת הַמַּיִם. הַמַּפְסִיקִין בֵּין אֲרָם לְאֶרֶץ כְּנָעַן:",1,0],[7,24,"וְאֶת הַיַּרְדֵּן. שֶׁגַּם הוּא הָיָה מַפְסִיק:",2,0],[7,25,"הֵבִיאוּ אֶל גִּדְעוֹן מֵעֵבֶר לַיַּרְדֵּן. בַּבֹּקֶר, כְּשֶׁעָבַר גִּדְעוֹן אֶת הַיַּרְדֵּן לִרְדֹּף אַחַר זֶבַח וְצַלְמֻנָּע:",1,0],[8,2,"מַה עָשִׂיתִי עַתָּה כָּכֶם. מַה חָשׁוּב מַה שֶּׁעָשִׂיתִי בִּתְחִלָּתוֹ, כְּמַה שֶּׁעֲשִׂיתֶם אַתֶּם בַּסּוֹף:",1,0],[8,2,"הֲלֹא טוֹב עֹלְלוֹת. שֶׁבָּאוּ לְיֶדְכֶם בַּסּוֹף מִתְּחִלַּת הַבָּצִיר שֶׁבָּצַרְנוּ אֲנִי וּמִשְׁפַּחְתִּי, שֶׁהֲרֵי בְּיֶדְכֶם נָתַן ה׳ אֶת הַמְּלָכִים:",2,0],[8,3,"וּמַה יָּכֹלְתִּי. לַעֲשׂוֹת שֶׁיְּהֵא חָשׁוּב כְּמַעֲשֵׂה שֶׁלָּכֶם:",1,0],[8,4,"עֹבֵר הוּא וּשְׁלֹשׁ מֵאוֹת הָאִישׁ. עוֹבְרִים אֶת הַיַּרְדֵּן אַחֲרֵי זֶבַח וְצַלְמֻנָּע שֶׁעָבְרוּ אֶת הַיַּרְדֵּן תְּחִלָּה, וְהָיוּ מַשְׁחִיתִים מֵעֵבֶר לַיַּרְדֵּן אֶת אֶרֶץ רְאוּבֵן וְגָד וּמְנַשֶּׁה, וְעָבַר שָׁם כְּדֵי לִנְקֹם אַף בָּהֶם:",1,0],[8,5,"לְאַנְשֵׁי סֻכּוֹת. יִשְׂרָאֵל הָיוּ:",1,0],[8,6,"הֲכַף זֶבַח וְצַלְמֻנָּע בְּיָדֶךָ. שֶׁאַתָּה מִתְפָּאֵר שֶׁהִצַּלְתָּנוּ מִיַּד מִדְיָן:",1,0],[8,7,"הַבַּרְקֳנִים. רונצי״ש בְּלַעַ״ז:",1,0],[8,10,"בַּקַּרְקֹר. שֵׁם מָקוֹם:",1,0],[8,11,"דֶּרֶךְ הַשְּׁכוּנֵי בָאֳהָלִים. דֶּרֶךְ אֶרֶץ קֵדָר וַעֲרָב הַשּׁוֹכְנִים בַּמִּדְבָּר בְּאָהֳלֵיהֶם, שֶׁרוֹעִים מִקְנֶה תָּמִיד וְאֵין דָּרִים בְּבָתִּים:",1,0],[8,11,"מִקֶּדֶם לְנֹבַח וְיׇגְבְּהָה. שֶׁהֵם עָרֵי יִשְׂרָאֵל, וְלֹא רָצָה לֵילֵךְ שָׁם אֶלָּא דֶּרֶךְ עֲקַלָּתוֹן, כְּדֵי שֶׁלֹּא יַרְגִּישׁוּ בָהֶם, וִיהוּמַּם פִּתְאוֹם:",2,0],[8,13,"מִלְמַעֲלֵה הֶחָרֶס. עַד שֶׁלֹּא שָׁקְעָה הַשֶּׁמֶשׁ, בְּעוֹד הַחַמָּה נִרְאֵית גָּבוֹהַּ:",1,0],[8,16,"וַיֹּדַע בָּהֶם. (תרגום:) וּתְבַר בְּהוֹן:",1,0],[8,18,"אֶחָד כְּתֹאַר בְּנֵי הַמֶּלֶךְ. יוֹנָתָן תִּרְגֵּם: אֶחָד הָיָה בָהֶם שֶׁתּוֹאֲרוֹ כְּתוֹאַר בְּנֵי הַמֶּלֶךְ. וְיֵשׁ לְפוֹתְרוֹ: כָּמוֹךָ כָּמוֹהֶם, תּוֹאַר אֶחָד לָכֶם, כִּי כְתוֹאַר בְּנֵי מְלָכִים הָיוּ:",1,0],[8,20,"וְלֹא שָׁלַף הַנַּעַר חַרְבּוֹ. לְהָרְגָם, שֶׁהָיָה יָרֵא מֵהֶם:",1,0],[8,21,"הַשַּׂהֲרֹנִים. לוינ״ש בְּלַעַ״ז, שֶׁל זָהָב:",1,0],[8,26,"הַשַּׂהֲרֹנִים וְהַנְּטִיפוֹת. (תרגום:) עִנְקְיָא וּכְלִילָא:",1,0],[8,27,"וַיַּעַשׂ אוֹתוֹ גִדְעוֹן לְאֵפוֹד. לִהְיוֹת לְזִכָּרוֹן עַל תְּשׁוּעָה גְדוֹלָה, לִרְאוֹת כַּמָּה הָיָה חֵילָם כָּבֵד שֶׁבְּנִזְמֵי חֲשׁוּבֵיהֶם הָיָה כָּל הַזָּהָב הַזֶּה:",1,0],[8,27,"וַיִּזְנוּ כָל יִשְׂרָאֵל אַחֲרָיו. לְאַחַר מִיתַת גִּדְעוֹן:",2,0],[8,33,"בַּעַל בְּרִית. כָּךְ שְׁמוֹ:",1,0],[8,35,"וְלֹא עָשׂוּ חֶסֶד וְגוֹ׳. שֶׁהָרְגוּ אֶת בָּנָיו, כְּמוֹ שֶׁכָּתוּב בָּעִנְיָן (שופטים ט:ה):",1,0],[9,4,"וּפֹחֲזִים. בְּהוּלִים בְּמַעֲשֵׂיהֶם לַעֲשׂוֹת בְּלֹא תְבוּנָה:",1,0],[9,6,"עִם אֵלוֹן מֻצָּב. (תרגום:) מֵישַׁר קָמְתָא - מִישׁוֹר שֶׁהָיוּ בּוֹ מַצֵּבוֹת:",1,0],[9,8,"הָלוֹךְ הָלְכוּ הָעֵצִים. מָשָׁל הוּא:",1,0],[9,8,"לַזַּיִת. עָתְנִיאֵל בֶּן קְנַז (שופטים א:יג), הַבָּא מִשֵּׁבֶט יְהוּדָה שֶׁנִּקְרָא זַיִת, שֶׁנֶּאֱמַר (ירמיהו יא:טז): זַיִת רַעֲנָן יְפֵה פְרִי תֹאַר וְגוֹ׳:",2,0],[9,9,"דִּשְׁנִי. לְשׁוֹן שׁוּמָן:",1,0],[9,10,"לַתְּאֵנָה. דְּבוֹרָה:",1,0],[9,11,"אֶת מָתְקִי. דְּבַשׁ דְּבוֹרִים:",1,0],[9,12,"לַגָּפֶן. גִּדְעוֹן, שֶׁהוּא מִזֶּרַע יוֹסֵף (שופטים ו:יא), שֶׁנֶּאֱמַר בּוֹ (בראשית מט:כב) בֵּן פֹּרָת, (ותרגם שם אונקלוס:) כְּגוּפָן דִּנְצִיב וְכוּ׳:",1,0],[9,13,"הַמְשַׂמֵּחַ אֱלֹהִים. שֶׁאֵין אוֹמְרִים הַלְוִיִּם שִׁיר שֶׁל הַקָּרְבָּן אֶלָּא עַל הַנְּסָכִים:",1,0],[9,14,"אֶל הָאָטָד. ספינ״ה בְּלַעַ״ז:",1,0],[9,15,"אִם בֶּאֱמֶת. שֶׁאֲנִי הָגוּן לַמַּלְכוּת:",1,0],[9,22,"וַיָּשַׂר. עַל כָּרְחָם נָהַג רַבָּנוּת וּבְגַאֲוָה:",1,0],[9,23,"רוּחַ רָעָה. שִׂנְאָה, שלנ״ש מלטלינ״ט בְּלַעַ״ז:",1,0],[9,26,"גַּעַל בֶּן עֶבֶד. מֵאוּמָּה אַחֶרֶת הָיָה:",1,0],[9,27,"וַיַּעֲשׂוּ הִלּוּלִים. (תרגום:) וַעֲבַדוּ חַנְגִין:",1,0],[9,28,"מִי אֲבִימֶלֶךְ וּמִי שְׁכֶם. מִי אֲבִימֶלֶךְ לִהְיוֹת שַׂר עַל שְׁכֶם וּמִי שְׁכֶם לִהְיוֹת עֲבָדִים לַאֲבִימֶלֶךְ, הֲלֹא בֶּן יְרֻבַּעַל הָיָה אֲבִימֶלֶךְ מִן עָפְרַת אֲבִי הָעֶזְרִי (לעיל ו:יא):",1,0],[9,28,"וּזְבֻל פְּקִידוֹ. וְזֶה פְּקִיד הָעִיר שֶׁשְּׁמוֹ ׳זְבוּל׳, פְּקִידוֹ שֶׁל אֲבִימֶלֶךְ הוּא, וַאֲדוֹנָיו אֵין לוֹ מִשְׁפַּט מְלוּכָה בָּעִיר וְאַף פְּקִידוֹ אֵינוֹ כְּלוּם:",2,0],[9,28,"עִבְדוּ אֶת אַנְשֵׁי חֲמוֹר. אִם בָּאתֶם לִקְנוֹת לָכֶם אֲדוֹנִים, בֹּאוּ וְעִבְדוּ אֶת אַנְשֵׁי חֲמוֹר, שֶׁהָיָה נְשִׂיא הָאָרֶץ מִקֶּדֶם (בראשית לד:ב):",3,0],[9,28,"וּמַדּוּעַ נַעַבְדֶנּוּ. לַאֲבִימֶלֶךְ:",4,0],[9,29,"וַיֹּאמֶר לַאֲבִימֶלֶךְ. וַיֹּאמֶר גַּעַל בִּפְנֵי זְבוּל, הוֹדִיעַ לַאֲבִימֶלֶךְ:",1,0],[9,29,"רַבֶּה צְבָאֲךָ וָצֵאָה. מִן הַמָּקוֹם שֶׁאַתָּה שָׁם, וְנִרְאֶה אֶת גְּדֻלָּתְךָ:",2,0],[9,31,"בְּתָרְמָה. כְּמוֹ בְּמִרְמָה, בְּתַרְמִית, כְּלוֹמַר: בַּלָּט וּבַסֵּתֶר:",1,0],[9,34,"אַרְבָּעָה רָאשִׁים. אַרְבָּעָה כִּתּוֹת:",1,0],[9,37,"מֵעִם טַבּוּר הָאָרֶץ. (תרגום:) מִן תּוּקְפָא דְאַרְעָא, מֵהַר הַגָּבוֹהַּ שֶׁבְּכֻלָּם:",1,0],[9,37,"אֵלוֹן מְעוֹנְנִים (תרגום:) מֵישַׁר מְעוֹנְנִים:",2,0],[9,42,"וַיֵּצֵא הָעָם הַשָּׂדֶה. אַנְשֵׁי שְׁכֶם:",1,0],[9,42,"וַיַּגִּידוּ. הַמַּגִּידִים לַאֲבִימֶלֶךְ, שֶׁיָּצְאוּ בְּנֵי הָעִיר אֶל הַשָּׂדֶה לַעֲשׂוֹת חֶפְצֵיהֶם:",2,0],[9,44,"פֶּתַח שַׁעַר הָעִיר. שֶׁלֹּא יוּכְלוּ לִיכָּנֵס:",1,0],[9,46,"צְרִיחַ. יַעַר שֶׁכָּפוּ אִילָנוֹת וּפְסָגִים סָבִיב סָבִיב, וְקוֹרִין אוֹתוֹ פלייש״ר בְּלַעַ״ז:",1,0],[9,46,"בֵּית אֵל בְּרִית. אוֹתוֹ צְרִיחַ הָיָה שֶׁל בַּעַל בְּרִית, שֵׁם שֶׁל עֲבוֹדָה זָרָה שֶׁלָּהֶם, וְצַלְמוֹן (פסוק מח), יַעַר הָיָה שָׁם וְיֵשׁ פּוֹתְרִין: צְרִיחַ, וודו״י בְּלַעַ״ז שֶׁעוֹשִׂין בַּקַּרְקַע:",2,0],[9,48,"שׂוֹכַת עֵצִים. עֲנַף עֵצִים:",1,0],[9,53,"פֶּלַח רֶכֶב. חֲתִיכַת אֶבֶן שֶׁל רֵחַיִם הָעֶלְיוֹנָה הַקְּרוּיָה רֶכֶב:",1,0],[9,53,"וַתָּרִץ. וַתְּרוֹצֵץ:",2,0],[9,54,"פֶּן יֹאמְרוּ לִי. פֶּן יֹאמְרוּ עָלַי:",1,0],[10,1,"בֶּן דּוֹדוֹ. כָּךְ שְׁמוֹ:",1,0],[10,4,"עֲיָרִים. (תרגום:) עוּלִין, סוּסִים בְּחוּרִים:",1,0],[10,4,"וּשְׁלֹשִׁים עֲיָרִים לָהֶם. וּשְׁלֹשִׁים עָרִים בְּלֹא חוֹמָה לָהֶם, לְכָךְ נִקְרְאוּ עֲיָרִים, לְשׁוֹן עֲיָירוֹת:",2,0],[10,6,"אֶת הַבְּעָלִים וְגוֹ׳. שֶׁבַע עֲבוֹדוֹת זָרוֹת נִמְנוּ כָּאן:",1,0],[10,6,"וַיַּעַזְבוּ אֶת ה׳ וְלֹא עֲבָדוּהוּ. אֲפִילוּ בְּשׁוּתָּפוּת עִם אֵלּוּ:",2,0],[10,8,"בַּשָּׁנָה הַהִיא. כְּשֶׁמֵּת יָאִיר:",1,0],[10,8,"אֲשֶׁר בְּעֵבֶר הַיַּרְדֵּן. אֶרֶץ רְאוּבֵן וְגָד וַחֲצִי הַמְּנַשֶּׁה, שֶׁהָיוּ שְׁכֵנֵיהֶם:",2,0],[10,11,"הֲלֹא מִמִּצְרַיִם. שֶׁבַע תְּשׁוּעוֹת יֵשׁ כָּאן, כְּנֶגֶד שֶׁבַע עֲבוֹדוֹת זָרוֹת שֶׁהָיוּ עוֹבְדִים:",1,0],[10,12,"וּמָעוֹן. שֵׁם אוּמָּה:",1,0],[10,16,"וַתִּקְצַר נַפְשׁוֹ בַּעֲמַל. כִּבְיָכוֹל לֹא הָיָה רַחֲבַת מָקוֹם לִסְבּוֹל וְלִכָּנֵס שָׁם צָרָה שֶׁהָיָה לוֹ בַּעֲמַל יִשְׂרָאֵל:",1,0],[10,17,"וַיִּצָּעֲקוּ. נֶאֶסְפוּ עַל יְדֵי כָּרוּז:",1,0],[11,4,"וַיִּלָּחֲמוּ בְנֵי עַמּוֹן. הִיא הָאֲמוּרָה לְמַעְלָה (י:ט):",1,0],[11,11,"אֶת כָּל דְּבָרָיו. הַתְּנַאי שֶׁבֵּינֵיהֶם:",1,0],[11,11,"לִפְנֵי ה׳ בַּמִּצְפָּה. לְמָקוֹם שֶׁנֶּאֶסְפוּ כֻּלָּם, שֶׁהַשְּׁכִינָה שׁוֹרָה עַל רוֹב צִבּוּר:",2,0],[11,16,"עַד יַם סוּף. בִּדְרוֹמָהּ שֶׁל אֶרֶץ אֱדוֹם, וְאֶרֶץ אֱדוֹם בִּדְרוֹמָהּ שֶׁל אֶרֶץ כְּנַעַן:",1,0],[11,17,"אֶעְבְּרָה נָּא בְאַרְצֶךָ. מִדָּרוֹם לְצָפוֹן, לִיכָּנֵס לְאֶרֶץ כְּנַעַן:",1,0],[11,17,"וְגַם אֶל מֶלֶךְ מוֹאָב. שֶׁהָיְתָה אַרְצוֹ בְּסוֹף אֶרֶץ אֱדוֹם, בְּמִזְרָחָהּ שֶׁל אֱדוֹם וּבִדְרוֹמָהּ שֶׁל אֶרֶץ יִשְׂרָאֵל:",2,0],[11,17,"וְלֹא אָבָה. מֹשֶׁה רְמָזָהּ בַּתּוֹרָה (דברים ב:כט): כַּאֲשֶׁר עָשׂוּ לִי בְּנֵי עֵשָׂו הַיּוֹשְׁבִים בְּשֵׂעִיר וְהַמּוֹאָבִים הַיּוֹשְׁבִים בְּעָר, כְּשֵׁם שֶׁאֱדוֹם לֹא נְתָנוּם לַעֲבֹר, כָּךְ מוֹאָב לֹא נְתָנוּם לַעֲבֹר:",3,0],[11,18,"וַיֵּלֶךְ בַּמִּדְבָּר. מִן הַמַּעֲרָב לַמִּזְרָח, בְּמֵיצַר דְּרוֹמִי שֶׁל אֱדוֹם וּמוֹאָב:",1,0],[11,18,"וַיָּסָב אֶת אֶרֶץ אֱדוֹם. כָּל דְּרוֹמָהּ:",2,0],[11,18,"וְאֶת אֶרֶץ מוֹאָב. כָּל דְּרוֹמָהּ, וּכְשֶׁהִגִּיעַ לְמִקְצוֹעַ דְּרוֹמִית מִזְרָחִית, פָּנָה אֶל הַצָּפוֹן לִסְבּוֹב אֶת מֵיצַר הַמִּזְרָחִי:",3,0],[11,18,"וַיָּבֹא מִמִּזְרַח שֶׁמֶשׁ לְאֶרֶץ מוֹאָב וַיַּחֲנוּן בְּעֵבֶר אַרְנוֹן. לְסוֹף מִזְרָחָהּ שֶׁל אֶרֶץ מוֹאָב, וְשָׁם הִתְחִילָה אֶרֶץ סִיחוֹן וְעוֹג, וְכָבְשׁוּ עֵבֶר הַיַּרְדֵּן בְּמִזְרַח אֶרֶץ כְּנַעַן וְעָבְרוּ הַיַּרְדֵּן, וְנִכְנְסוּ לָהּ לְאֶרֶץ כְּנַעַן דֶּרֶךְ הַמִּזְרָח:",4,0],[11,22,"וַיִּירְשׁוּ וְגוֹ׳ מֵאַרְנוֹן וְעַד הַיַּבֹּק. שֶׁאַתָּה אוֹמֵר שֶׁהוּא שֶׁלְּךָ (פסוק יג), הֵם מִסִּיחוֹן לָקְחוּ:",1,0],[11,22,"וּמִן הַמִּדְבָּר וְעַד הַיַּרְדֵּן. מִדְבָּרוֹת הָיוּ שָׁם לִפְנֵי הַיַּרְדֵּן:",2,0],[11,26,"עַל יְדֵי אַרְנוֹן. אֵצֶל אַרְנוֹן, שֶׁהָיוּ מִמּוֹאָב, וְיָדְעוּ שֶׁלֹּא הָיָה לָהֶם לַעֲבֹר עֲלֵיהֶם, שֶׁהֲרֵי מִסִּיחוֹן כְּבָשׁוּם (במדבר כא:כד), שֶׁלְּקָחָם מִמֶּלֶךְ מוֹאָב (שם שם כו):",1,0],[11,26,"שְׁלֹשׁ מֵאוֹת שָׁנָה. מִשֶּׁכָּבְשׁוּ אֶת הָאָרֶץ בִּימֵי יְהוֹשֻׁעַ עַד יִפְתָּח מִכָּאן יֵשׁ לִלְמוֹד שְׁנוֹת הַשּׁוֹפְטִים הַנִּזְכָּרִים עַד הֵנָּה, אִם שְׁנֵי הַשִּׁעְבּוּד שֶׁל כָּל אוּמָּה נִמְנִים בְּתוֹךְ יְמֵי הַשּׁוֹפֵט אִם לָאו. שָׁנִינוּ בְּסֵדֶר עוֹלָם (פרק יב): יְהוֹשֻׁעַ פִּרְנֵס אֶת יִשְׂרָאֵל עֶשְׂרִים וּשְׁמוֹנֶה שָׁנָה, וְאֵין לוֹ מִקְרָא מִמִּי לִלְמוֹד. עָתְנִיאֵל (לעיל ג:יא), אַרְבָּעִים שָׁנָה, וּשְׁנֵי שִׁעְבּוּד שֶׁל כּוּשַׁן רִשְׁעָתַיִם (שם שם ח) בִּכְלָלָם. אַחֲרָיו אֵהוּד (שם שם ל), שְׁמוֹנִים שָׁנָה, שְׁמוֹנֶה עֶשְׂרֵה שָׁנִים שִׁעְבּוּד שֶׁל עֶגְלוֹן (שם שם יד) בְּתוֹכָם, הֲרֵי מֵאָה אַרְבָּעִים וּשְׁמוֹנֶה שָׁנָה. דְּבוֹרָה (שם ה:לא) אַרְבָּעִים שָׁנָה, וּשְׁנֵי שִׁעְבּוּד יָבִין (שם ד:ג) בְּתוֹכָם, הֲרֵי מֵאָה שְׁמוֹנִים וּשְׁמוֹנֶה. אַחֲרָיו, שֶׁבַע שָׁנִים שֶׁל שִׁעְבּוּד מִדְיָן (שם ו:א), וְאַרְבָּעִים שֶׁל גִּדְעוֹן (שם ח:כח), וְשָׁלֹשׁ שֶׁל אֲבִימֶלֶךְ (שם ט:כב), הֲרֵי מָאתַיִם שְׁלֹשִׁים וּשְׁמוֹנֶה שָׁנִים. אַחֲרָיו, עֶשְׂרִים וְשָׁלֹשׁ שֶׁל תּוֹלָע (שם י:ב), וְעֶשְׂרִים וּשְׁתַּיִם שֶׁל יָאִיר (שם י:ג), אֶלָּא שֶׁעָלְתָה שָׁנָה אַחַת לִשְׁנֵיהֶם, וּשְׁמוֹנֶה עֶשְׂרֵה שֶׁל בְּנֵי עַמּוֹן (שם שם ח) עַד שֶׁלֹּא בָּא יִפְתָּח, הֲרֵי שְׁלֹשׁ מֵאוֹת:",2,0],[11,29,"עָבַר בְּנֵי עַמּוֹן. אֶל בְּנֵי עַמּוֹן:",1,0],[11,33,"אָבֵל כְּרָמִים. (תרגום:) מֵישַׁר כַּרְמַיָּא:",1,0],[11,35,"הַכְרֵעַ הִכְרַעְתִּנִי. לְשׁוֹן נְקֵבָה, וְדוֹמֶה לוֹ (שיר השירים ד:ט): לִבַּבְתִּנִי אֲחוֹתִי כַלָּה:",1,0],[11,35,"הָיִית בְּעֹכְרָי. כָּל דָּמִי נֶעְכָּר, קִפַּחְתְּ אֶת רַגְלִי:",2,0],[11,37,"וְיָרַדְתִּי עַל הֶהָרִים. לְשׁוֹן יְלָלָה הוּא, וְדוּגְמָתוֹ (ישעיהו טו:ג): עַל גַּגּוֹתֶיהָ וּבִרְחוֹבוֹתֶיהָ כֻּלֹּה יְיֵלִיל יָרַד בִּבְכִי, הַמִּתְעַצֵּב בִּבְכִי עַד שֶׁגּוּפוֹ מִשְׁתַּבֵּר. וּבְמִדְרַשׁ אַגָּדָה דּוֹרֵשׁ רַבִּי תַּנְחוּמָא (בחוקותי ה): עַל הֶהָרִים. לִפְנֵי סַנְהֶדְרִין, שֶׁמָּא יִמְצְאוּ פֶּתַח לְנִדְרְךָ:",1,0],[11,38,"וַתֵּבְךְּ עַל בְּתוּלֶיהָ. מִדְּלָא כְתִיב עַל בְּתוּלוֹתֶיהָ, מַשְׁמַע בְּתוּלִים מַמָּשׁ:",1,0],[11,39,"וַתְּהִי חֹק. גָּזְרוּ שֶׁלֹּא יַעֲשֶׂה אָדָם עוֹד כֵּן, שֶׁאִלּוּ הָלַךְ אֵצֶל פִּנְחָס, אוֹ הוּא בָּא אֶצְלוֹ, הָיָה מַתִּיר לוֹ נִדְרוֹ, עָמְדוּ בִּגְדֻלָּתָן, וּמִבֵּין שְׁנֵיהֶם אָבְדָה, וְנִפְרַע מֵהֶם, פִּנְחָס נִסְתַּלְּקָה שְׁכִינָה הֵימֶנּוּ, שֶׁנֶּאֱמַר בְּדִבְרֵי הַיָּמִים (א ט:כ): לְפָנִים ה׳ עִמּוֹ, לָמַדְנוּ שֶׁבְּסוֹפוֹ אֵינוֹ עִמּוֹ, וְיִפְתָּח הוּכָּה בִּשְׁחִין וְנִפּוּל אֵבָרִים, שֶׁנֶּאֱמַר (לקמן יב:ז): וַיִּקָּבֵר בְּעָרֵי גִלְעָד. וְיֵשׁ עוֹד לִפְתֹּר: וַתְּהִי חֹק בְּיִשְׂרָאֵל. מְחֻבָּר לְמִקְרָא שֶׁלְּאַחֲרָיו:",1,0],[11,40,"מִיָּמִים יָמִימָה תֵּלַכְנָה וְגוֹ׳. הַדָּבָר הַזֶּה קָבְעוּ עֲלֵיהֶם לְחֹק:",1,0],[11,40,"לְתַנּוֹת. לְקוֹנֵן:",2,0],[12,1,"וַיַּעֲבֹר צָפוֹנָה. וַיַּעֲבֹר אֶת הַיַּרְדֵּן, וְהָלְכוּ לִצְפוֹן עֵבֶר הַיַּרְדֵּן, אֶל הַגִּלְעָד:",1,0],[12,4,"כִּי אָמְרוּ פְּלִיטֵי אֶפְרַיִם אַתֶּם גִּלְעָד. פְּחוּתִים שֶׁבְּאֶפְרַיִם הָיוּ מְבַזִּים אֶת הַגִּלְעָד, וְאוֹמְרִים לָהֶם: מָה אַתֶּם גִּלְעָד חֲשׁוּבִים בְּתוֹךְ אֶפְרַיִם וּבְתוֹךְ מְנַשֶּׁה, כֵּן תִּרְגֵּם יוֹנָתָן:",1,0],[12,5,"וַיִּלְכֹּד גִּלְעָד אֶת מַעְבְּרוֹת וְגוֹ׳. הָיוּ שׁוֹמְרִים בִּמְקוֹם הַמַּעְבָּרוֹת:",1,0],[12,6,"אֱמָר נָא שִׁבֹּלֶת. שִׁבֹּלֶת הַנָּהָר הַזֶּה אֶעֱבֹר:",1,0],[12,6,"וְלֹא יָכִין לְדַבֵּר כֵּן. שֶׁהָיוּ מְגַמְגְּמִים בִּלְשׁוֹנָם:",2,0],[12,8,"אִבְצָן. זֶה בֹּעַז:",1,0],[13,4,"יַיִן וְשֵׁכָר. (תרגום:) חַמַר חֲדַת וְעַתִּיק:",1,0],[13,5,"וּמוֹרָה. תַּעַר, עַל שֵׁם שֶׁמּוֹרֶה וּמַשְׁלִיךְ אֶת הַשֵּׂעָר:",1,0],[13,7,"וְאַל תֹּאכְלִי כָּל טֻמְאָה. דְּבָרִים הָאֲסוּרִים לְנָזִיר:",1,0],[13,8,"לַנַּעַר הַיּוּלָד. הֶעָתִיד לְהִוָּלֵד:",1,0],[13,11,"אַחֲרֵי אִשְׁתּוֹ. אַחַר עֲצָתָהּ:",1,0],[13,12,"מַה יִּהְיֶה מִשְׁפַּט הַנַּעַר וּמַעֲשֵׂהוּ. (תרגום:) מָה חֲזִי לְמֶעֱבַד לְעוּלֵימָא וּמָה נַעֲבִיד לֵיהּ:",1,0],[13,15,"נַעְצְרָה נָּא אוֹתָךְ. נֶאֱסֹף אוֹתְךָ אֶל הַבַּיִת:",1,0],[13,17,"כִּי יָבֹא דְבָרְךָ. אִם יָבֹא לָנוּ שְׁלִיחוּת דָּבָר מֵאִתְּךָ, מִשֶּׁנֵּדַע וְנַכִּיר אֶת שְׁמֶךָ:",1,0],[13,17,"וְכִבַּדְנוּךָ. וְנַעֲשֶׂה מַה שֶּׁתִּשְׁלַח לָנוּ:",2,0],[13,18,"וְהוּא פֶלִאי. מְכֻסֶּה, תָּמִיד הוּא מִשְׁתַּנֶּה וְאֵין יָדוּעַ לְמָה מִשְׁתַּנֶּה הַיּוֹם (ספרי נשא מב):",1,0],[13,23,"וְכָעֵת. הַזֹּאת:",1,0],[13,23,"לֹא הִשְׁמִיעָנוּ כָּזֹאת. לֹא הָיָה מַשְׁמִיעֵנוּ בְּשׂוֹרָה זוֹ אִם רְאוּיִים אָנוּ לָמוּת:",2,0],[13,25,"לְפַעֲמוֹ. לָבֹא בְּקִרְבּוֹ לִפְעָמִים:",1,0],[14,4,"כִּי תֹאֲנָה הוּא מְבַקֵּשׁ. עֲלִילָה לְהִתְגָּרוֹת בָּם:",1,0],[14,7,"וַיְדַבֵּר לָאִשָּׁה. עַל הָאִשָּׁה, דִּבֵּר לִקְרוֹבֶיהָ, כֵּן תִּרְגֵּם יוֹנָתָן:",1,0],[14,8,"עֲדַת דְּבוֹרִים. (תרגום:) קִינָא דְדַבְרַיָּתָא, כְּנִיסַת דְּבוֹרִים:",1,0],[14,9,"וַיִּרְדֵּהוּ. לְשׁוֹן הַבְדָּלַת דִּבּוּק שֶׁל כָּל דָּבָר הַנִּדְבָּק, וְכֵן לְעִנְיַן פַּת הַנִּדְבֶּקֶת בַּתַּנּוּר, נִקְרֵאת הַבְדָּלָתוֹ רְדִיָּה, (שבת קיז ב): הָרוֹדֶה פַּת מִן הַתַּנּוּר, (בבא מציעא סד א): הָרוֹדֶה אֶת כַּוַּרְתּוֹ, עַל שֵׁם שֶׁהַדְּבַשׁ עָשׂוּי עַל יְדֵי חַלּוֹת שֶׁעוֹשֶׂה מְדֻבָּק בְּדָפְנֵי הַכְּלִי בְּכָל צְדָדִין מִדּוֹפֶן אֶל דּוֹפֶן, כְּמִדַּת עוֹגֶל הַכְּלִי, וְכֵן תִּרְגֵּם יוֹנָתָן: וַיִּרְדֵּהוּ, וּנְסַחְיֵהּ:",1,0],[14,10,"וַיֵּרֶד אָבִיהוּ אֶל הָאִשָּׁה. (תרגום:) עַל עִסְקֵי אִתְּתָא:",1,0],[14,11,"מֵרֵעִים. חֲבֵרִים לְשׁוֹשְׁבִינוּת:",1,0],[14,15,"וַיְהִי בַּיּוֹם הַשְּׁבִיעִי. לִימוֹת הַשַּׁבָּת, וְלֹא שְׁבִיעִי לַמִּשְׁתֶּה, וְהוּא רְבִיעִי לִימֵי הַמִּשְׁתֶּה:",1,0],[14,15,"הַלְיָרְשֵׁנוּ קְרָאתֶם לָנוּ הֲלֹא. תִּרְגֵּם יוֹנָתָן: הַלְמִסְכְּנוּתָנָא קְרִיתוֹן יָתָנָא הָלְכָא:",2,0],[14,17,"שִׁבְעַת הַיָּמִים. הַנּוֹתָרִים מִשִּׁבְעַת הַיָּמִים, מֵרְבִיעִי וְאֵילָךְ:",1,0],[14,18,"בְּטֶרֶם יָבֹא הַחַרְסָה. לִפְנֵי שְׁקִיעַת הַחַמָּה, שֶׁעֲדַיִן הָיָה לָהֶם שֵׁהוּת עַד הָעֶרֶב:",1,0],[14,18,"חֲרַשְׁתֶּם בְּעֶגְלָתִי. מָשָׁל הוּא (תרגום:) אִילּוּלְפוֹן בְּדַקְתּוּן בְּאִתְּתִי:",2,0],[14,19,"רוּחַ ה׳. (תרגום:) רוּחַ גְּבוּרָה מִן קֳדָם ה׳:",1,0],[14,19,"חֲלִיצוֹתָם. מַלְבּוּשִׁים שֶׁחָלַץ מֵעֲלֵיהֶן:",2,0],[14,20,"לְמֵרֵעֵהוּ. לְאֶחָד מִשּׁוֹשְׁבִינָיו נְתָנָהּ:",1,0],[15,3,"נִקֵּיתִי הַפַּעַם. בְּדִין אֶעֱשֶׂה לָהֶם הָרָעָה:",1,0],[15,4,"וַיֶּפֶן. אֶת הַזְּנָבוֹת זָנָב אֶל זָנָב. וַיִּפֶן, מַשְׁמַע הוּא עַצְמוֹ פָּנָה (שמות לב טו); וַיֶּפֶן, מַשְׁמַע הִפְנָה אֶת אֲחֵרִים, וְכֵן שִׁמּוּשׁ כָּל תֵּיבָה שֶׁפֹּעַל שֶׁלָּהּ בְּה״א; (שמות א כ): וַיִּרֶב הָעָם; (איכה ב ה): וַיֶּרֶב בְּבַת יְהוּדָה תַּאֲנִיָּה; (מלכים ב כה כא): וַיִּגֶל יְהוּדָה מֵעַל אַדְמָתוֹ, גָּלָה; (שם ב: יח יא): וַיֶּגֶל מֶלֶךְ אַשּׁוּר אֶת יִשְׂרָאֵל אַשּׁוּרָה, הִגְלָה:",1,0],[15,6,"חֲתַן הַתִּמְנִי. חֲתַן הַפְּלִשְׁתִּי אֲשֶׁר בְּתִמְנָה (לעיל יד א):",1,0],[15,7,"אִם תַּעֲשׂוּן כָּזֹאת. וְשֶׁמָּא רְגִילִין אַתֶּם בְּכָךְ, לָתֵת אִשְׁתּוֹ שֶׁל זֶה לָזֶה:",1,0],[15,8,"שׁוֹק עַל יָרֵךְ. (תרגום:) פָּרְשִׁין עִם רַגְלָאִין, רוֹכֵב סוּס אֵינוֹ נִשְׁעָן עַל יְרֵכוֹ כִּי אִם עַל שׁוֹקוֹ, רֶגֶל אֶחָד נָתוּן בַּבַּרְזֶל הַתָּלוּי בַּמֶּרְכֶּבֶת:",1,0],[15,8,"בִּסְעִיף. בְּנִקְרַת סֶלַע עֵיטָם, וַחֲבֵרוֹ (ישעיהו נז:ה): סְעִיפֵי הַסְּלָעִים, (שם י:לג): מְסָעֵף פֹּארָה:",2,0],[15,9,"וַיִּנָּטְשׁוּ. וַיִּתְפַּזְּרוּ:",1,0],[15,9,"בַּלֶּחִי. שֵׁם מָקוֹם:",2,0],[15,10,"לָמָה עֲלִיתֶם עָלֵינוּ. הֲלֹא עֲבָדִים אֲנַחְנוּ לָכֶם:",1,0],[15,10,"לֶאֱסוֹר אֶת שִׁמְשׁוֹן. שֶׁתַּאַסְרוּהוּ וְתַסְגִּירוּהוּ לָנוּ:",2,0],[15,13,"לֹא כִּי אָסוֹר נֶאֱסָרְךָ. לֹא נַהֲרוֹג אוֹתְךָ, כִּי אִם אָסוֹר נֶאֱסָרְךָ:",1,0],[15,14,"רוּחַ ה׳. (תרגום:) רוּחַ גְּבוּרָה מִן קֳדָם ה׳:",1,0],[15,14,"אֱסוּרָיו. קִשּׁוּרָיו:",2,0],[15,15,"טְרִיָּה. לַחָה, וְרָאִיתִי בְּסֵפֶר רְפוּאוֹת שֶׁקּוֹרֵא לַלֵּחָה שֶׁיּוֹצֵא מִן הַמַּכָּה: ׳טְרִיָּה׳:",1,0],[15,16,"חֲמוֹר חֲמֹרָתָיִם. בִּלְחִי הַחֲמוֹר לִצְבּוֹר צְבָרִים רַבִּים, (תרגום:) בְּלוּעָא דִחמָרָא רְמֵיתִנוּן דְּגוֹרִין:",1,0],[15,19,"אֶת הַמַּכְתֵּשׁ. גּוּמָּא שֶׁהַשֵּׁן יוֹשֶׁבֶת בָּהּ, עֲשׂוּיָה כְּעֵין מַכְתֶּשֶׁת:",1,0],[15,19,"עֵין הַקּוֹרֵא. מַעְיָן שֶׁבָּא עַל יְדֵי זַעֲקַת הַקּוֹרֵא אֶל ה׳:",2,0],[16,2,"לַעַזָּתִים לֵאמֹר. לְאַנְשֵׁי עַזָּה נֶאֱמַר:",1,0],[16,2,"וַיִּתְחָרְשׁוּ. נָהֲגוּ עַצְמָן בִּשְׁתִיקָה:",2,0],[16,3,"וַיִּסָּעֵם. וַיַּעַקְרֵם מִמְּקוֹמָם:",1,0],[16,7,"יְתָרִים. חֲבָלִים דַּקִּים:",1,0],[16,9,"וְלֹא נוֹדַע כֹּחוֹ. לֹא הוּצְרַךְ לְהִתְחַזֵּק בְּנַתְּקוֹ אוֹתָם:",1,0],[16,11,"בַּעֲבוֹתִים. חֲבָלִים גַּסִּים:",1,0],[16,13,"מַחְלְפוֹת. קְוֻצּוֹת, פלוני״ש בְּלַעַ״ז:",1,0],[16,13,"עִם הַמַּסָּכֶת. עֵץ שֶׁהַגַּרְדִּי מֵיסֵךְ בּוֹ אֶת הַשְּׁתִי, וְשֵׁם הָעֵץ אנשובל״א מַסֶּכֶת, אורטר״א בְּלַעַ״ז:",2,0],[16,16,"וַתְּאַלְצֵהוּ. דְּחָקַתּוֹ, וְאֵין לוֹ דִּמְיוֹן:",1,0],[16,18,"וַתֵּרֶא דְלִילָה כִּי הִגִּיד לָהּ. נִכָּרִין דִּבְרֵי אֱמֶת:",1,0],[16,19,"וַתִּקְרָא לָאִישׁ. לִשְׁלוּחָן שֶׁל סְרָנִים:",1,0],[16,21,"וַיּוֹרִידוּ אוֹתוֹ עַזָּתָה. מְקוֹם תְּחִלַּת קִלְקוּלוֹ:",1,0],[16,21,"וַיְהִי טוֹחֵן. בָּרֵחַיִם, מְלָאכָה כְּבֵדָה וְרַבּוֹתֵינוּ (סוטה י א) פֵּרְשׁוּ מַה שֶּׁפֵּרְשׁוּ:",2,0],[16,25,"בֵּין הָעַמּוּדִים. אֲשֶׁר הַבַּיִת נָכוֹן עֲלֵיהֶם:",1,0],[16,26,"וַהֲמִישֵׁנִי. פאלפא״ר בְּלַעַ״ז, כְּמוֹ (בראשית כז:יב): ״אוּלַי יְמֻשֵּׁנִי״:",1,0],[16,28,"זָכְרֵנִי נָא. זְכֹר עֶשְׂרִים שָׁנָה שֶׁשָּׁפַטְתִּי אֶת יִשְׂרָאֵל, וְלֹא אָמַרְתִּי לְאֶחָד מֵהֶם הַעֲבֵר לִי מַקֵּל זֶה מִמָּקוֹם לְמָקוֹם:",1,0],[16,28,"נְקַם אַחַת מִשְּׁתֵי עֵינַי. וּשְׂכַר עַיִן הַשֵּׁנִית הַנַּח לִי לָעוֹלָם הַבָּא, וְכָאן פְּרַע לִי שְׂכַר אַחַת מֵהֶן:",2,0],[16,29,"וַיִּלְפֹּת. וַיֹּאחַז, אינברצ״א בְּלַעַ״ז, כְּמוֹ (רות ג:ח): ״וַיֶּחֱרַד הָאִישׁ וַיִּלָּפֵת״, נֶאֱחַז בִּזְרוֹעוֹת הָאִשָּׁה:",1,0],[17,1,"וַיְהִי אִישׁ מֵהַר אֶפְרָיִם. אַף עַל פִּי שֶׁנִּכְתְּבוּ שְׁתֵּי פָּרָשִׁיּוֹת הַלָּלוּ בְּסוֹף הַסֵּפֶר, שֶׁל מִיכָה וְשֶׁל פִּלֶגֶשׁ בַּגִּבְעָה, בִּתְחִלַּת הַשּׁוֹפְטִים הָיָה, בִּימֵי עָתְנִיאֵל בֶּן קְנַז, שֶׁנֶּאֱמַר (שופטים יח:לא): ״וַיָּשִׂימוּ לָהֶם אֶת פֶּסֶל מִיכָה וְגוֹ׳ כָּל יְמֵי הֱיוֹת בֵּית אֱלֹהִים בְּשִׁילֹה״, לָמַדְנוּ שֶׁכָּל יְמֵי שִׁילֹה הָיָה דְּמוּת שֶׁל מִיכָה, וּבְפִלֶגֶשׁ בַּגִּבְעָה נֶאֱמַר עַל יְבוּס שֶׁבִּירוּשָׁלַיִם (שופטים יט:יב): ״לֹא נָסוּר אֶל עִיר נָכְרִי״, לָמַדְנוּ שֶׁעֲדַיִן לֹא כָּבְשׁוּ אֶת יְרוּשָׁלַיִם:",1,0],[17,2,"אֲשֶׁר לֻקַּח לָךְ. אֲשֶׁר נִגְנַב מִמֵּךְ, וְיֵשׁ לוֹ דוֹמֶה (שמואל א כא:ו): ״כִּי אִשָּׁה עֲצוּרָה לָנוּ״, עֲצוּרָה מִמֶּנּוּ:",1,0],[17,2,"וְאַתְּ אָלִית. קִלְלַת כָּל מִי שֶׁגְּנָבוֹ, וְגַם אָמַרְתְּ הַקְּלָלָה בְּאָזְנַי:",2,0],[17,2,"הִנֵּה הַכֶּסֶף. אֲנִי מוֹדֶה לָךְ עָלָיו שֶׁהוּא בְּיָדִי שֶׁאֲנִי לְקַחְתִּיו:",3,0],[17,3,"וַיָּשֶׁב אֶת אֶלֶף וּמֵאָה הַכֶּסֶף לְאִמּוֹ. אָמַר לְהַחֲזִירוֹ לָהּ, וּבַמָּקוֹם שֶׁהוּא שָׁם הֲרֵי הוּא בִּרְשׁוּתֵךְ:",1,0],[17,3,"הַקְדֵּשׁ הִקְדַּשְׁתִּי אֶת הַכֶּסֶף מִיָּדִי לִבְנִי. קִבַּלְתִּי עָלַי לְמָסְרוֹ מִיָּדִי לְיָדְךָ לְשֵׁם דְּמוּת וּמַסֵּכָה, תְּנֵהוּ לִי עַתָּה וּמִיָּדִי אֲנִי אֲשִׁיבֶנּוּ אֵלֶיךָ יֵשׁ אוֹמְרִים שֶׁהָאִשָּׁה הַזֹּאת הִיא דְּלִילָה, לְפִי שֶׁכָּתוּב (לעיל טז:ה): ״אֶלֶף וּמֵאָה כֶּסֶף״, וְטָעוּת הוּא בְּיָדָם, שֶׁהַרְבֵּה שָׁנִים קָדַם מִיכָה לְשִׁמְשׁוֹן, אַךְ הַפָּרָשִׁיּוֹת נִסְמְכוּ עַל הַכֶּסֶף הָרָע שֶׁשָּׁוֶה כָּאן וְכָאן, וְכֶסֶף שֶׁל פּוּרְעָנוּת הָיוּ שְׁנֵיהֶם:",2,0],[17,5,"בֵּית אֱלֹהִים. בֵּית עֲבוֹדָה זָרָה, וְכֵן כָּל ׳אֱלֹהִים׳ הָאֲמוּרִים בְּפָרָשָׁה זוֹ חוֹל, חוּץ מִזֶּה (שופטים יח:לא): ״כָּל יְמֵי הֱיוֹת בֵּית הָאֱלֹהִים בְּשִׁילֹה״ (שבועות לה ב):",1,0],[17,5,"וַיְמַלֵּא אֶת יַד אַחַד. חֲנָכוֹ לַעֲבוֹדַת הַדְּמוּת לִהְיוֹת כֹּהֵן לְפָנָיו, כָּל חִנּוּךְ דָּבָר שֶׁאָדָם נִכְנָס בּוֹ לְשֵׁם גְּדֻלָּה קָרוּי מִלּוּי יָדַיִם, רישוושטי״ר בְּלַעַ״ז; וּכְשֶׁנּוֹתְנִין פְּקִידוּת לְאָדָם, קוֹרִין לְמַתָּן רישוישטי״ר בְּלַעַ״ז:",2,0],[17,7,"מִמִּשְׁפַּחַת יְהוּדָה. וְהוּא לֵוִי מִן הָאֵם וְרַבּוֹתֵינוּ אָמְרוּ (בבא בתרא קט ב): לְפִי שֶׁעָשָׂה מַעֲשֵׂה מְנַשֶּׁה שֶׁבָּא מִיהוּדָה, קְרָאוֹ מִמִּשְׁפַּחַת יְהוּדָה, וְהוּא לֵוִי בֶּן גֵּרְשׁוֹם בֶּן מֹשֶׁה רַבֵּינוּ הָיָה, כְּמוֹ שֶׁמְּפֹרָשׁ בָּעִנְיָן (שופטים יח:ל): ״וִיהוֹנָתָן בֶּן גֵּרְשׁוֹם וְגוֹ׳״:",1,0],[17,8,"לַעֲשׂוֹת דַּרְכּוֹ. דֶּרֶךְ הֲלִיכָתוֹ:",1,0],[17,9,"בַּאֲשֶׁר אֶמְצָא. פַּרְנָסָתִי לְהִשְׂתַּכֵּר:",1,0],[17,10,"לַיָּמִים. לְסוֹף שָׁנָה:",1,0],[17,10,"וְעֵרֶךְ בְּגָדִים. זוּג חֲלִיפַת בְּגָדִים שֶׁהֵם עֵרֶךְ וְסֵדֶר לְכָל בְּנֵי אָדָם כְּפִי הָרָאוּי לָהֶם לְשָׁנָה:",2,0],[17,10,"וְעֵרֶךְ בְּגָדִים. אפרליימנ״ט בְּלַעַ״ז:",3,0],[17,10,"וּמִחְיָתֶךָ. וּמְזוֹנוֹתֶיךָ:",4,0],[17,10,"וַיֵּלֶךְ הַלֵּוִי. אַחַר עֲצָתוֹ:",5,0],[18,1,"כִּי לֹא נָפְלָה לוֹ. יְרֻשָּׁה כְּפִי הָרָאוּי לָהֶם בְּאֶרֶץ מְכֻבֶּשֶׁת, כְּמוֹ שֶׁנֶּאֱמַר בִּיהוֹשֻׁעַ (יהושע יט:מז): ״וַיֵּצֵא גְבוּל בְּנֵי דָן מֵהֶם״, וְאַף מִכָּאן יֵשׁ לִלְמֹד שֶׁהָיָה מַעֲשֶׂה זֶה בִּתְחִלַּת הַשּׁוֹפְטִים מִיָּד:",1,0],[18,3,"מִי הֱבִיאֲךָ הֲלֹם. יֵשׁ כָּאן תְּמִיהוֹת הַרְבֵּה, (בבא בתרא קי:) לֹא מִזַּרְעוֹ שֶׁל מֹשֶׁה רַבֵּינוּ אַתָּה, שֶׁנֶּאֱמַר בּוֹ (שמות ג:ה): ״אַל תִּקְרַב הֲלֹם״, (שם ד:יא): ״מִי שָׂם פֶּה לָאָדָם״, (שם ד:ב): ״מַה זֶּה בְיָדֶךָ״:",1,0],[18,5,"שְׁאַל נָא בֵאלֹהִים. בַּתְּרָפִים שֶׁמְּדַבְּרִים עַל יְדֵי מְכַשְּׁפוֹת:",1,0],[18,6,"נֹכַח ה׳ דַּרְכְּכֶם. נֹכַח הַקָּדוֹשׁ בָּרוּךְ הוּא גָּלוּי, כִּי זֶה אֵין בּוֹ מַמָּשׁ:",1,0],[18,7,"וְאֵין מַכְלִים דָּבָר. אֵין אֶחָד מֵהֶם צָרִיךְ לַחֲבֵרוֹ שֶׁיַּחֲזִירֶנּוּ רֵיקָם וְיַכְלִימֶנּוּ, כְּמוֹ שֶׁנֶּאֱמַר בְּסוֹף הָעִנְיָן (פסוק י): ״אֵין מַחְסוֹר כָּל דָּבָר״, כָּךְ שָׁמַעְתִּי:",1,0],[18,7,"יוֹרֵשׁ עֶצֶר. יוֹרְשִׁים מוּעָטִים, שֶׁאִם יַהַרְגוּ אֶת אֵלּוּ, אֵין עוֹד עוֹרְרִין נִלְחָמִים עִם הַמַּחֲזִיקִים בַּנַּחֲלָה:",2,0],[18,7,"וּרְחוֹקִים הֵמָּה. מֵעֶזְרַת צִידוֹנִים:",3,0],[18,7,"וְדָבָר אֵין לָהֶם עִם אָדָם. שׁוּם בְּרִית כְּרוּתָה שֶׁיָּבֹאוּ לְעֶזְרָתָם לְעֵת הַצֹּרֶךְ:",4,0],[18,8,"מָה אַתֶּם. כְּלוֹמַר מָה אַתֶּם מְשִׁיבִים דָּבָר, מַה מְּצָאתֶם בַּמָּקוֹם שֶׁנָּפַל לָנוּ גוֹרָלֵנוּ, מָה הָעָם, הֶחָזָק הוּא הֲרָפֶה:",1,0],[18,9,"וְאַתֶּם מַחְשִׁים. מִתְעַצְּלִים:",1,0],[18,21,"וְאֶת הַכְּבוּדָּה. מַשָּׂאוֹת, כָּל דָּבָר שֶׁהוּא כָּבֵד בַּהֲלִיכָתוֹ שֶׁאֵינוֹ יָכוֹל לָרוּץ אִם יִרְדְּפוּ בְּנֵי הַמָּקוֹם אַחֲרֵיהֶם:",1,0],[18,21,"הַכְּבוּדָּה. פיזנטו״מא בְּלַעַ״ז:",2,0],[18,23,"וַיַּסֵּבּוּ פְּנֵיהֶם. בְּנֵי דָן אֶל הַקּוֹרְאִים אֲלֵיהֶם:",1,0],[18,24,"וּמַה לִּי עוֹד. וּמַה נִּשְׁאַר לִי עוֹד:",1,0],[18,25,"אֲנָשִׁים מָרֵי נֶפֶשׁ. כַּעֲסָנִים שֶׁיֵּשׁ בְּסִיעָתֵנוּ:",1,0],[18,27,"לַיִשׁ. שֵׁם הָעִיר, וּבְסֵפֶר יְהוֹשֻׁעַ (יהושע יט:מז) קוֹרֵא שְׁמָהּ ׳לֶשֶׁם׳, עַל שֵׁם שֶׁמָּצְאוּ שָׁם אֶבֶן טוֹבָה שֶׁשְּׁמָהּ ׳לֶשֶׁם׳, וְהִיא הָיְתָה עַל הַחֹשֶׁן לְשֵׁבֶט דָּן, שְׁמוֹ כָּתוּב עַל ׳לֶשֶׁם׳, וְיָדְעוּ שֶׁבֶּאֱמֶת הִיא נַחֲלָתָם:",1,0],[18,30,"בֶּן מְנַשֶּׁה. מִפְּנֵי כְּבוֹדוֹ שֶׁל מֹשֶׁה כָּתוּב נוּ״ן לְשַׁנּוֹת אֶת הַשֵּׁם, וְנִכְתַּב תְּלוּיָה לוֹמַר שֶׁלֹּא הָיָה מְנַשֶּׁה אֶלָּא מֹשֶׁה:",1,0],[18,30,"עַד יוֹם גְּלוֹת הָאָרֶץ. בִּימֵי סַנְחֵרִיב בְּגָלוּת רִאשׁוֹנָה:",2,0],[19,2,"וַתִּזְנֶה עָלָיו פִּילַגְשׁוֹ. זָנְתָה מִבֵּיתוֹ אֶל הַחוּץ כָּל לְשׁוֹן זְנוּת אֵינוֹ אֶלָּא לְשׁוֹן ׳יוֹצֵאת׳ (תרגום אונקלוס בראשית לד:לא): נַפְקַת בָּרָא, יוֹצֵאת מִבַּעְלָהּ לֶאֱהוֹב אֶת אֲחֵרִים:",1,0],[19,6,"הוֹאֶל נָא וְלִין. הַלַּיְלָה:",1,0],[19,9,"רָפָה. הַשֶּׁמֶשׁ מִגְּבוּרָתוֹ וְנָטָה לַעֲרוֹב:",1,0],[19,9,"הִנֵּה חֲנוֹת הַיּוֹם. עֵת שֶׁכָּל הוֹלְכֵי דְרָכִים נוֹטִים לַחֲנוֹת בַּבַּיִת:",2,0],[19,12,"עַד גִּבְעָה. גִּבְעַת בִּנְיָמִן:",1,0],[19,13,"וְלַנּוּ. כְּמוֹ וְלַנְנוּ, דַּגְשׁוּת הַנּוּ״ן בִּמְקוֹם נוּ״ן שְׁנִיָּה:",1,0],[19,18,"וְאֶת בֵּית ה׳. לְשִׁילֹה אֲנִי הוֹלֵךְ:",1,0],[19,21,"וַיָּבָל לַחֲמוֹרִים. וַיִּתֵּן יְבוּל לַחֲמוֹרִים, ׳וַיָּבָל׳ אפרוונד״ר בְּלַעַ״ז:",1,0],[19,22,"וְנֵדָעֶנּוּ. מִשְׁכַּב זָכוּר:",1,0],[19,28,"וְאֵין עוֹנֶה. כִּי מֵתָה:",1,0],[20,2,"פִּנּוֹת כָּל הָעָם. (תרגום:) רֵישֵׁי כָּל עַמָּא:",1,0],[20,5,"דִּמּוּ לַהֲרֹג. כִּוְּנוּ לַהֲרֹג, אנישמינט״ו בְּלַעַ״ז:",1,0],[20,10,"לַעֲשׂוֹת לְבוֹאָם. לְבִיאָתָם זוֹ לְגִבְעַת בִּנְיָמִין ׳כְּכָל הַנְּבָלָה׳ וְגוֹ׳:",1,0],[20,11,"חֲבֵרִים. שָׁוִים בְּעֵצָה אַחַת:",1,0],[20,12,"בְּכָל שִׁבְטֵי בִנְיָמִן. עֲשָׂרָה שְׁבָטִים נֶחְשְׁבוּ עֲשָׂרָה מִשְׁפְּחוֹתָיו, שֶׁיִּהְיוּ מֵרָחֵל שְׁנֵים עָשָׂר שְׁבָטִים:",1,0],[20,16,"אִטֵּר יַד יְמִינוֹ. גְּמוּדֵי יַד יְמִינָם, לֹא הָיוּ שׁוֹלְטִים בָּהּ כְּאִלּוּ הָיְתָה אֲטוּמָה, כְּמוֹ (תהלים סט:טז): ״אַל תֶּאְטַר עָלַי בְּאֵר פִּיהָ״:",1,0],[20,16,"כָּל זֶה. שְׁבַע מֵאוֹת אִישׁ הַלָּלוּ:",2,0],[20,16,"אֶל הַשַּׂעֲרָה. לְחוּט הַשֵּׂעָר:",3,0],[20,16,"וְלֹא יַחֲטִא. לֹא יִשְׁגֶּה:",4,0],[20,18,"יְהוּדָה בַתְּחִלָּה. אֲבָל לֹא בָחֲנוּ לִשְׁאוֹל אִם לְנַצֵּחַ אִם לִינָּצֵחַ, וּבָאַחֲרוֹנָה שֶׁבָּחֲנוּ, אָמַר (פסוק כח): ״עֲלוּ כִּי מָחָר אֶתְּנֶנּוּ בְיָדֶךָ״, הִשְׁכִּימוּ וְהִשְׁלִימוּ דִּבְרֵיהֶם:",1,0],[20,21,"וַיַּשְׁחִיתוּ. נֶעֶנְשׁוּ עַל שֶׁלֹּא קִנְּאוּ כְּמוֹ כֵן בְּמַעֲשֵׂה דְּמוּת מִיכָה שֶׁהָיָה כְּבָר:",1,0],[20,33,"בְּבַעַל תָּמָר. בְּמֵישַׁר יְרִיחוֹ:",1,0],[20,33,"מֵגִיחַ. נִמְשָׁךְ, כְּמוֹ (איוב מ:כג): ״יָגִיחַ יַרְדֵּן אֶל פִּיהוּ״; (תהלים כב:י): ״גֹחִי מִבָּטֶן״:",2,0],[20,33,"מִמַּעֲרֵה גָבַע. מִמָּקוֹם צַר, עֶרְוָתָהּ וְגִלּוּיָהּ שֶׁל גִּבְעַת בִּנְיָמִין, מְקוֹם תּוֹרְפָה שֶׁלָּהּ שֶׁהִיא נוֹחָה לִיכָּבֵשׁ מִשָּׁם, כְּמוֹ (בראשית מב:ט): ״לִרְאוֹת אֶת עֶרְוַת הָאָרֶץ בָּאתֶם״:",3,0],[20,36,"וַיִּתְּנוּ אִישׁ יִשְׂרָאֵל. אֲשֶׁר בַּשָּׂדֶה, מָקוֹם לְבִנְיָמִן לִבְרֹחַ אֶל הַגִּבְעָה, כִּי סָמְכוּ יִשְׂרָאֵל עַל הָאוֹרֵב שֶׁיֵּצְאוּ לִקְרָאתָם:",1,0],[20,37,"וַיִּמְשֹׁךְ הָאוֹרֵב. מָשַׁךְ בַּשּׁוֹפָר; דָּבָר אַחֵר: מָשַׁךְ בַּשּׁוֹפָר הָעָם אֲשֶׁר אִתּוֹ, אֶל הָעִיר:",1,0],[20,38,"וְהַמּוֹעֵד הָיָה. מִתְּחִלָּה הָיָה אוֹת בֵּין יִשְׂרָאֵל וּבֵין הָאוֹרֵב, לִהְיוֹת הָאוֹרֵב מַרְבֶּה לְהַעֲלוֹת עֲשַׁן הָעִיר, וְיָבִינוּ יִשְׂרָאֵל אֲשֶׁר לָכַד הָאוֹרֵב אֶת הַגִּבְעָה:",1,0],[20,38,"מַשְׂאַת הֶעָשָׁן. גֹּבַהּ הֶעָשָׁן:",2,0],[20,39,"וַיַּהֲפֹךְ אִישׁ יִשְׂרָאֵל. עַכְשָׁיו חוֹזֵר לִתְחִלַּת הַדְּבָרִים וְשׁוֹנֶה וּמְפָרֵשׁ, עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף שֶׁכָּתַבְנוּ לְמַעְלָה (פסוק לה), כֵּיצַד נָפְלוּ וְהֵיכָן נָפְלוּ:",1,0],[20,42,"וַאֲשֶׁר מֵהֶעָרִים. הָאוֹרֵב שֶׁנִּכְנַס בָּעִיר, מַשְׁחִיתִים אוֹתוֹ בְּתוֹךְ הַשֵּׁבֶט, בְּתוֹךְ הָעִיר:",1,0],[20,43,"כִּתְּרוּ אֶת בִּנְיָמִן. הִקִּיפוּ אֶת בִּנְיָמִן כְּכֶתֶר הַמַּקִּיף אֶת הָרֹאשׁ, וְכֵן (תהלים כב:יג): ״אַבִּירֵי בָשָׁן כִּתְּרוּנִי״, וְכֵן (חבקוק א:ד): ״כִּי רָשָׁע מַכְתִּיר אֶת הַצַּדִּיק״, וְכֵן גַּם בִּלְשׁוֹן עֲטָרָה נִקְרֵאת הַקָּפָה (שמואל א כג:כו): ״וְשָׁאוּל וַאֲנָשָׁיו עֹטְרִים אֶל דָּוִד וְאֶל אֲנָשָׁיו לְתָפְשָׂם״:",1,0],[20,43,"הִרְדִיפֻהוּ. קוֹרְאִים אַחֲרָיו רְדִיפָה, צוֹעֲקִים זֶה לָזֶה לִרְדֹּף:",2,0],[20,43,"מְנוּחָה הִדְרִיכֻהוּ. אֵצֶל הֶעָרִים שֶׁהֵם נוֹחִים בָּהֶם, שָׁם הִדְבִּיקוּהוּ:",3,0],[20,43,"הִדְרִיכֻהוּ. הִשִּׂיגוּהוּ, וְיֵשׁ דֻּגְמָתוֹ בִּלְשׁוֹן גְּמָרָא (כתובות ס ב): רְהַט בַּתְרֵיהּ פַּרְסָא בְּחָלָא וְלֹא אַדְרְכֵיהּ:",4,0],[20,43,"עַד נֹכַח הַגִּבְעָה. מִמִּזְרָחָהּ שֶׁל גִּבְעָה:",5,0],[20,44,"וַיִּפְּלוּ מִבִּנְיָמִן שְׁמוֹנָה עָשָׂר אֶלֶף. בַּשָּׂדֶה בְּתוֹךְ הַמִּלְחָמָה:",1,0],[20,45,"וַיְעֹלְלֻהוּ. הֲרִיגָה אַחַר הֲרִיגָה, כְּעוֹלְלוֹת שֶׁאַחַר הַבָּצִיר:",1,0],[20,45,"חֲמֵשֶׁת אֲלָפִים אִישׁ. הֲרֵי עֶשְׂרִים וּשְׁלֹשָׁה אֶלֶף:",2,0],[20,45,"עַד גִּדְעֹם. שֵׁם מָקוֹם:",3,0],[20,45,"וַיַּכּוּ מִמֶּנּוּ אַלְפַּיִם אִישׁ. הֲרֵי עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף הָאָמוּר לְמַעְלָה (פסוק לה), וְהַמֵּאָה הַכְּתוּבִים לְמַעְלָה (שם), לֹא פֵּרַשׁ הֵיכָן נָפְלוּ:",4,0],[20,48,"שָׁבוּ אֶל בְּנֵי בִנְיָמִן. בְּכָל הֶעָרִים:",1,0],[20,48,"מֵעִיר מְתֹם. הֵתַמּוּ כָּל יוֹשְׁבֵי הֶעָרִים:",2,0],[20,48,"וְעַד בְּהֵמָה. וַאֲנָשִׁים בִּכְלַל ׳מְתוֹם׳ הָיוּ, שֶׁ׳מְּתוֹם׳ לְשׁוֹן כְּלָיָה הוּא וְיֵשׁ לִתְמֹהַּ עַל אֶלֶף הֵיכָן הֵם, שֶׁהֲרֵי עֶשְׂרִים וְשִׁשָּׁה אֶלֶף הִתְפַּקְּדוּ מִן הֶעָרִים, וּמִן הַגִּבְעָה שֵׁשׁ מֵאוֹת, וְכָאן מָנָה בַּנּוֹפְלִים עֶשְׂרִים וַחֲמִשָּׁה אֶלֶף וּמֵאָה אִישׁ, וְשֵׁשׁ מֵאוֹת נִמְלְטוּ אֶל סֶלַע הָרִמּוֹן, וְהָאֶלֶף בָּרְחוּ אֶל הֶעָרִים וְנָפְלוּ לְמָחֳרָת כְּשֶׁשָּׁבוּ בְּנֵי יִשְׂרָאֵל אֶל עָרֵי בִנְיָמִן לְהַחֲרִים הַנָּשִׁים וְהַטַּף:",3,0],[21,3,"לְהִפָּקֵד. לְהִגָּרַע:",1,0],[21,6,"וַיִּנָּחֲמוּ. שָׁבוּ לַחֲשֹׁב עֲלֵיהֶם מַחְשֶׁבֶת פְּלֵיטָה:",1,0],[21,12,"אַרְבַּע מֵאוֹת. נַעֲרָה בְתוּלָה הוֹשִׁיבוּם עַל פִּי חָבִיּוֹת שֶׁל יַיִן, בְּעוּלָה רֵיחָהּ נוֹדֵף, בְּתוּלָה אֵין רֵיחָהּ נוֹדֵף:",1,0],[21,14,"וְלֹא מָצְאוּ לָהֶם. לֹא סִפְּקוּ לָהֶם:",1,0],[21,17,"יְרֻשַּׁת פְּלֵיטָה. נַחֲלַת הַשֵּׁבֶט נִשְׁאֲרָה רֵיקָנִית, הָבוּ עֵצָה שֶׁיּוֹלִידוּ בָנִים וְיַחֲזִיקוּ בְּנַחֲלָתָם הַפְּלֵיטָה הַנִּשְׁאֶרֶת, וְלֹא יִמָּחֶה שֵׁבֶט מִיִּשְׂרָאֵל:",1,0],[21,19,"מִזְרְחָה הַשֶּׁמֶשׁ לַמְסִלָּה. בְּמִזְרָחָהּ שֶׁל מְסִלָּה, שִׁילֹה בִּצְפוֹנָהּ שֶׁל בֵּית אֵל וּבִדְרוֹמָהּ שֶׁל לְבוֹנָה, וּבְמִזְרָחָהּ שֶׁל מְסִלָּה הָעוֹלָה מִבֵּית אֵל שְׁכֶמָה:",1,0],[21,22,"לָרִיב אֵלֵינוּ. לָלֶכֶת אֵלֵינוּ בַּמִּלְחָמָה:",1,0],[21,22,"וְאָמַרְנוּ אֲלֵיהֶם חָנּוּנוּ אוֹתָם. רִחַמְנוּ עֲלֵיהֶם כִּי אֵינָם יוֹדְעִים מַה לַּעֲשׂוֹת, ׳כִּי לֹא לָקַחְנוּ אִישׁ אִשְׁתּוֹ בַּמִּלְחָמָה׳ שֶׁל יָבֵשׁ גִּלְעָד אֶלָּא לְאַרְבַּע מֵאוֹת אִישׁ מֵהֶם, וְאִם עַל הַשְּׁבוּעָה אַתֶּם מַקְפִּידִים, לֹא עָוֹן לָכֶם בַּדָּבָר ׳כִּי לֹא אַתֶּם נְתַתֶּם לָהֶם׳ אֶת בְּנוֹתֵיכֶם שֶׁתְּהֵא לָכֶם אַשְׁמָה בַּדָּבָר וְשָׁלוֹם לָכֶם אַל תִּירָאוּ:",2,0]]);
